/* =====================================================================
   ATP — layout shell e componentes
   ===================================================================== */

/* ----- Layout ----- */
.app-shell {
  --mode-content-max-width: var(--content-max-width);
  --mode-page-padding: var(--space-5);
  --mode-page-padding-mobile: var(--space-3);
  --mode-desktop-page-padding: var(--space-6);
  --mode-section-gap: var(--space-4);
  --mode-surface-padding: var(--space-4);
  --mode-card-padding: var(--space-4);
  --mode-card-radius: var(--radius-md);
  --mode-row-padding: var(--space-3);
  --mode-row-radius: var(--radius-sm);
  --mode-row-min-height: 64px;
  --mode-surface-shadow: var(--shadow-sm);
  --mode-row-shadow: var(--shadow-xs);
  --mode-button-min-height: 40px;
  --mode-compact-button-min-height: 34px;
  --mode-input-min-height: var(--density-touch-target);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(circle at 92% 4%, rgba(216, 244, 73, 0.16), transparent 19rem),
    url("./assets/surface-court-lines-soft.png") center top / 1600px auto no-repeat,
    linear-gradient(180deg, rgba(232, 247, 239, 0.76) 0%, rgba(245, 247, 246, 0) 300px),
    var(--color-bg);
  color: var(--color-text);
}

.app-shell--player {
  --mode-content-max-width: var(--player-content-max-width);
  --mode-page-padding: var(--player-page-padding);
  --mode-page-padding-mobile: var(--player-page-padding-mobile);
  --mode-section-gap: var(--player-section-gap);
  --mode-surface-padding: var(--player-surface-padding);
  --mode-card-padding: var(--player-card-padding);
  --mode-card-radius: var(--player-card-radius);
  --mode-row-padding: var(--player-row-padding);
  --mode-row-radius: var(--player-row-radius);
  --mode-row-min-height: var(--player-row-min-height);
  --mode-surface-shadow: var(--player-surface-shadow);
  --mode-row-shadow: var(--player-row-shadow);
  --mode-button-min-height: var(--player-button-min-height);
  --mode-compact-button-min-height: var(--player-compact-button-min-height);
  --mode-input-min-height: var(--player-input-min-height);
  background:
    radial-gradient(circle at 88% 2%, rgba(216, 244, 73, 0.13), transparent 18rem),
    url("./assets/surface-court-lines-soft.png") center top / 1500px auto no-repeat,
    linear-gradient(180deg, rgba(231, 248, 240, 0.62) 0%, rgba(245, 247, 246, 0) 280px),
    var(--color-bg);
}

.app-shell--competition {
  --mode-content-max-width: var(--competition-content-max-width);
  --mode-page-padding: var(--competition-page-padding);
  --mode-page-padding-mobile: var(--competition-page-padding-mobile);
  --mode-section-gap: var(--competition-section-gap);
  --mode-surface-padding: var(--competition-surface-padding);
  --mode-card-padding: var(--competition-card-padding);
  --mode-card-radius: var(--competition-card-radius);
  --mode-row-padding: var(--competition-row-padding);
  --mode-row-radius: var(--competition-row-radius);
  --mode-row-min-height: var(--competition-row-min-height);
  --mode-surface-shadow: var(--competition-surface-shadow);
  --mode-row-shadow: var(--competition-row-shadow);
  --mode-button-min-height: var(--competition-button-min-height);
  --mode-compact-button-min-height: var(--competition-compact-button-min-height);
  --mode-input-min-height: var(--competition-input-min-height);
  background:
    radial-gradient(circle at 90% 0%, rgba(216, 244, 73, 0.12), transparent 18rem),
    url("./assets/surface-court-lines-soft.png") center top / 1500px auto no-repeat,
    linear-gradient(180deg, rgba(230, 247, 251, 0.72) 0%, rgba(245, 247, 246, 0) 300px),
    var(--color-bg);
}

.app-shell--management {
  --mode-content-max-width: var(--management-content-max-width);
  --mode-page-padding: var(--management-page-padding);
  --mode-page-padding-mobile: var(--management-page-padding-mobile);
  --mode-section-gap: var(--management-section-gap);
  --mode-surface-padding: var(--management-surface-padding);
  --mode-card-padding: var(--management-card-padding);
  --mode-card-radius: var(--management-card-radius);
  --mode-row-padding: var(--management-row-padding);
  --mode-row-radius: var(--management-row-radius);
  --mode-row-min-height: var(--management-row-min-height);
  --mode-surface-shadow: var(--management-surface-shadow);
  --mode-row-shadow: var(--management-row-shadow);
  --mode-button-min-height: var(--management-button-min-height);
  --mode-compact-button-min-height: var(--management-compact-button-min-height);
  --mode-input-min-height: var(--management-input-min-height);
  background:
    radial-gradient(circle at 88% 0%, rgba(216, 244, 73, 0.14), transparent 18rem),
    url("./assets/surface-court-lines-soft.png") center top / 1500px auto no-repeat,
    linear-gradient(180deg, rgba(232, 247, 239, 0.78) 0%, rgba(245, 247, 246, 0) 320px),
    var(--color-bg);
}

.app-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 255, 255, 0.86);
  border-bottom: 1px solid rgba(200, 210, 223, 0.78);
  box-shadow: 0 1px 0 rgba(8, 18, 37, 0.03);
  padding: 10px var(--space-4);
  backdrop-filter: blur(18px);
}

.app-header-inner {
  width: 100%;
  max-width: var(--content-max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}

.app-header-greeting {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  min-width: 0;
}

.app-header-greeting .avatar {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: linear-gradient(145deg, #ffffff, var(--color-primary-soft));
  border: 1px solid var(--color-green-200);
  color: var(--color-primary-strong);
  display: grid;
  place-items: center;
  font-weight: 900;
  overflow: hidden;
  flex-shrink: 0;
  box-shadow: var(--shadow-xs);
}

.app-header-greeting .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.app-header-greeting .greeting-label {
  font-size: var(--font-size-xs);
  color: var(--color-text-subtle);
  margin: 0;
  font-weight: 800;
  letter-spacing: 0;
}

.app-header-greeting .greeting-name {
  font-size: var(--font-size-md);
  font-weight: 900;
  color: var(--color-text);
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Work SaaS home: dense operational console, not the legacy card stack. */
.app-shell--management .work-home-console {
  color: var(--pdark-text-main);
  display: grid;
  gap: 12px;
}

.app-shell--management .work-home-title {
  display: grid;
  gap: 3px;
}

.app-shell--management .work-home-title span {
  color: var(--pdark-accent);
  font-size: 0.76rem;
  font-weight: 950;
  text-transform: uppercase;
}

.app-shell--management .work-home-title h2 {
  font-size: clamp(2rem, 4vw, 3.15rem);
  letter-spacing: 0;
  line-height: 0.98;
  margin: 0;
}

.app-shell--management .work-home-title p {
  color: var(--pdark-text-muted);
  font-weight: 760;
  margin: 0;
}

.app-shell--management .work-home-hero {
  align-items: center;
  background:
    linear-gradient(90deg, rgba(5, 14, 28, 0.96), rgba(12, 27, 45, 0.72), rgba(8, 51, 38, 0.42)),
    url("./assets/pdark-court-management-hero.png") center / cover no-repeat;
  border: 1px solid rgba(166, 198, 229, 0.18);
  border-radius: 10px;
  box-shadow: var(--pdark-card-shadow);
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 122px;
  padding: 18px 20px;
}

.app-shell--management .work-home-hero h3 {
  font-size: clamp(1.35rem, 2.4vw, 2rem);
  letter-spacing: 0;
  margin: 0 0 4px;
}

.app-shell--management .work-home-hero p {
  color: var(--pdark-text-muted);
  font-weight: 760;
  margin: 0;
}

.app-shell--management .work-home-hero > strong {
  background: rgba(15, 23, 42, 0.72);
  border: 1px solid rgba(166, 198, 229, 0.16);
  border-radius: 999px;
  padding: 8px 12px;
}

.app-shell--management .work-home-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.app-shell--management .work-home-hero-actions button,
.app-shell--management .work-home-card button {
  background: rgba(15, 28, 46, 0.92);
  border: 1px solid rgba(166, 198, 229, 0.2);
  border-radius: 8px;
  color: var(--pdark-text-main);
}

.app-shell--management .work-home-hero-actions button.primary,
.app-shell--management .work-home-card button.primary {
  background: linear-gradient(135deg, #22c55e, #16a34a);
  border-color: rgba(74, 222, 128, 0.42);
  color: #ecfdf5;
}

.app-shell--management .work-home-hero-actions button:not(.primary):hover,
.app-shell--management .work-home-hero-actions button:not(.primary):focus-visible,
.app-shell--management .work-home-card button:not(.primary):hover,
.app-shell--management .work-home-card button:not(.primary):focus-visible {
  background: rgba(22, 38, 60, 0.98);
  border-color: rgba(74, 222, 128, 0.34);
  color: var(--pdark-text-main);
}

.app-shell--management .work-home-metrics {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.app-shell--management .work-home-metrics button,
.app-shell--management .work-home-metrics [role="button"],
.app-shell--management .work-home-metrics > * {
  background: rgba(12, 27, 45, 0.82);
  border: 1px solid rgba(166, 198, 229, 0.14);
  border-radius: 9px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 4px;
  min-height: 72px;
  text-align: left;
}

.app-shell--management .work-home-metrics strong {
  display: block;
  font-size: clamp(1.25rem, 2vw, 1.8rem);
  line-height: 1;
  color: var(--pdark-text-main);
}

.app-shell--management .work-home-metrics span,
.app-shell--management .work-home-metrics small {
  display: block;
  max-width: 100%;
  line-height: 1.18;
  color: var(--pdark-text-muted);
}

.app-shell--management .work-home-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: minmax(320px, 1.1fr) minmax(280px, 0.9fr) minmax(260px, 0.72fr);
}

.app-shell--management .work-home-card {
  background:
    linear-gradient(180deg, rgba(12, 27, 45, 0.9), rgba(5, 14, 28, 0.86)),
    url("./assets/pdark-finance-operation-texture.png") center / cover no-repeat;
  border: 1px solid rgba(166, 198, 229, 0.15);
  border-radius: 10px;
  box-shadow: var(--pdark-card-shadow);
  display: grid;
  gap: 10px;
  min-height: 230px;
  padding: 12px;
}

.app-shell--management .work-home-card header {
  align-items: center;
  display: flex;
  gap: 10px;
  justify-content: space-between;
}

.app-shell--management .work-home-card h3 {
  font-size: 1rem;
  margin: 0;
}

.app-shell--management .work-home-card .place-action-queue {
  background: rgba(3, 10, 22, 0.28);
  border-radius: 10px;
  box-shadow: none;
  padding: 10px;
}

.app-shell--management .work-home-card .place-action-queue > div {
  grid-template-columns: minmax(0, 1fr);
}

.app-shell--management .work-home-card .place-action-queue button,
.app-shell--management .work-home-card .place-action-queue span {
  width: 100%;
}

.app-shell--management .work-home-timeline {
  display: grid;
  gap: 0;
}

.app-shell--management .work-home-timeline button {
  align-items: center;
  background: transparent;
  border: 0;
  border-top: 1px solid rgba(166, 198, 229, 0.1);
  color: var(--pdark-text-main);
  display: grid;
  gap: 4px;
  grid-template-columns: 90px minmax(0, 1fr) auto;
  padding: 11px 2px;
  text-align: left;
}

.app-shell--management .work-home-timeline span {
  color: var(--pdark-text-muted);
  font-weight: 850;
}

.app-shell--management .work-home-timeline em {
  background: rgba(34, 197, 94, 0.14);
  border: 1px solid rgba(34, 197, 94, 0.28);
  border-radius: 999px;
  color: #bbf7d0;
  font-style: normal;
  font-weight: 900;
  padding: 4px 8px;
}

.app-shell--management .work-home-shortcuts {
  display: grid;
  gap: 8px;
  grid-template-columns: 1fr 1fr;
}

.app-shell--management .work-home-shortcuts button {
  background: rgba(15, 33, 54, 0.82);
  border: 1px solid rgba(166, 198, 229, 0.16);
  color: var(--pdark-text-main);
  min-height: 42px;
}

.app-shell--management .work-home-empty,
.app-shell--management .work-home-timeline p {
  color: var(--pdark-text-muted);
  font-weight: 760;
  margin: 0;
}

@media (max-width: 1180px) {
  .app-shell--management .work-home-grid,
  .app-shell--management .work-home-metrics {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 720px) {
  .app-shell--management .work-home-hero,
  .app-shell--management .work-home-grid,
  .app-shell--management .work-home-metrics,
  .app-shell--management .work-home-shortcuts {
    grid-template-columns: 1fr;
  }
}

/* Work SaaS V1 shell: desktop topbar context for unit, search and quick create. */
.work-saas-topbar-context {
  display: none;
}

@media (min-width: 960px) {
  .app-shell--management .app-header-inner {
    gap: clamp(18px, 2vw, 32px);
  }

  .app-shell--management .app-header-actions {
    flex: 1;
    justify-content: flex-end;
    min-width: 0;
  }

  .work-saas-topbar-context {
    display: grid;
    grid-template-columns: minmax(180px, 260px) minmax(260px, 1fr) auto;
    align-items: center;
    gap: 10px;
    flex: 1;
    max-width: 820px;
    min-width: 0;
    position: relative;
  }

  .work-saas-topbar-context > small {
    grid-column: 1 / 2;
    margin-top: -8px;
    color: var(--muted);
    font-size: 0.72rem;
    font-weight: 800;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .work-unit-select,
  .work-global-search,
  .work-create-btn {
    min-height: 42px;
    border: 1px solid rgba(189, 211, 238, 0.18);
    border-radius: 10px;
    background: rgba(8, 18, 32, 0.82);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  }

  .work-unit-select {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2px;
    padding: 6px 10px;
  }

  .work-unit-select span {
    color: var(--muted);
    font-size: 0.66rem;
    font-weight: 900;
    line-height: 1;
    text-transform: uppercase;
  }

  .work-unit-select select {
    width: 100%;
    min-width: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--text);
    font: inherit;
    font-size: 0.86rem;
    font-weight: 900;
    outline: none;
  }

  .work-global-search {
    display: flex;
    align-items: center;
    min-width: 0;
    padding: 0 14px;
    color: rgba(221, 231, 244, 0.72);
    font-size: 0.86rem;
    font-weight: 800;
    position: relative;
  }

  .work-global-search input {
    background: transparent;
    border: 0;
    color: #f8fafc;
    font: inherit;
    font-size: 0.86rem;
    font-weight: 850;
    min-width: 0;
    outline: none;
    width: 100%;
  }

  .work-global-search input::placeholder {
    color: rgba(221, 231, 244, 0.72);
  }

  .work-global-search-panel,
  .work-create-menu {
    background:
      linear-gradient(180deg, rgba(12, 27, 45, 0.98), rgba(7, 16, 31, 0.98)),
      url("./assets/pdark-messages-chat-bg.png") center / cover no-repeat;
    border: 1px solid rgba(128, 164, 197, 0.28);
    border-radius: 14px;
    box-shadow: 0 24px 58px rgba(0, 0, 0, 0.46);
    display: grid;
    gap: 4px;
    max-height: min(430px, calc(100vh - 90px));
    overflow: auto;
    padding: 8px;
    position: absolute;
    right: 0;
    top: calc(100% + 8px);
    width: min(420px, 92vw);
    z-index: 90;
  }

  .work-global-search-panel {
    left: 0;
    right: auto;
  }

  .work-global-search-panel > button,
  .work-create-menu > button {
    background: rgba(15, 28, 46, 0.9);
    border: 1px solid rgba(128, 164, 197, 0.18);
    border-radius: 10px;
    color: #f8fafc;
    cursor: pointer;
    display: grid;
    gap: 3px;
    min-height: 52px;
    padding: 10px 12px;
    text-align: left;
  }

  .work-global-search-panel > button:hover,
  .work-global-search-panel > button:focus-visible,
  .work-create-menu > button:hover,
  .work-create-menu > button:focus-visible {
    background: rgba(34, 197, 94, 0.14);
    border-color: rgba(34, 197, 94, 0.35);
    outline: none;
  }

  .work-global-search-panel strong,
  .work-create-menu strong {
    color: #ffffff;
    font-size: 0.86rem;
    font-weight: 950;
  }

  .work-global-search-panel span,
  .work-create-menu span {
    color: rgba(203, 213, 225, 0.75);
    font-size: 0.74rem;
    font-weight: 800;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .work-create-btn {
    padding: 0 18px;
    border-color: rgba(44, 214, 109, 0.4) !important;
    background: linear-gradient(180deg, #26cf66 0%, #12a24c 100%) !important;
    color: #ffffff !important;
    font-weight: 950;
    cursor: pointer;
    position: relative;
  }

  .work-create-btn:hover,
  .work-create-btn:focus-visible,
  .work-create-btn[aria-expanded="true"] {
    border-color: rgba(74, 222, 128, 0.64) !important;
    background: linear-gradient(180deg, #31dd73 0%, #16a34a 100%) !important;
    box-shadow: 0 14px 34px rgba(34, 197, 94, 0.2);
    color: #ffffff !important;
    outline: none;
  }

  .work-create-menu {
    right: 0;
    top: calc(100% + 8px);
    width: min(320px, 86vw);
  }
}

@media (max-width: 1230px) {
  .work-saas-topbar-context {
    grid-template-columns: minmax(170px, 240px) auto;
    max-width: 520px;
  }

  .work-global-search {
    display: none;
  }
}

.greeting-name-line {
  align-items: center;
  display: flex;
  gap: 8px;
  min-width: 0;
}

.greeting-name-line > span {
  background: rgba(34, 197, 94, 0.13);
  border: 1px solid rgba(34, 197, 94, 0.25);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  flex: 0 0 auto;
  font-size: 0.68rem;
  font-weight: 950;
  line-height: 1;
  padding: 4px 7px;
}

.app-header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  position: relative;
}

.app-mode-switch {
  align-items: center;
  background: var(--color-surface-subtle);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  display: inline-flex;
  gap: 2px;
  padding: 3px;
}

.app-mode-switch button {
  border: 0;
  border-radius: var(--radius-pill);
  min-height: 32px;
  padding: 6px 12px;
}

.app-mode-switch button.active {
  background: var(--color-primary);
  box-shadow: var(--shadow-sm);
  color: var(--color-primary-fg);
}

/* ----- ATP DNA primitives ----- */
.app-page-header,
.app-action-panel,
.app-object-row,
.app-compact-empty {
  color: var(--color-text);
}

.app-page-header {
  align-items: flex-start;
  display: flex;
  gap: var(--space-4);
  justify-content: space-between;
  margin-bottom: var(--mode-section-gap, var(--space-4));
}

.app-page-header-copy {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
}

.app-page-eyebrow,
.app-action-panel-copy > span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  letter-spacing: 0;
  line-height: var(--line-title);
  text-transform: uppercase;
}

.app-page-header h1,
.app-action-panel h2 {
  color: var(--color-text);
  font-size: var(--font-size-2xl);
  font-weight: 950;
  letter-spacing: 0;
  line-height: var(--line-tight);
  margin: 0;
}

.app-page-header p,
.app-action-panel p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 750;
  line-height: var(--line-body);
  margin: 0;
  max-width: 68ch;
}

.app-page-meta,
.app-page-header-actions,
.app-action-panel-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.app-action-panel {
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(200, 210, 223, 0.78);
  border-left: 4px solid var(--color-primary);
  border-radius: var(--mode-card-radius, var(--radius-md));
  box-shadow: var(--mode-surface-shadow, var(--shadow-sm));
  display: grid;
  gap: var(--space-3);
  padding: var(--mode-card-padding, var(--space-4));
}

.app-action-panel--urgent {
  background: linear-gradient(180deg, #fff7ed, rgba(255, 255, 255, 0.94));
  border-color: #fed7aa;
  border-left-color: var(--color-warning);
}

.app-action-panel--success {
  background: linear-gradient(180deg, var(--color-primary-soft), rgba(255, 255, 255, 0.94));
  border-color: var(--color-green-200);
}

.app-action-panel-copy {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
}

.app-action-panel-body {
  display: grid;
  gap: var(--space-2);
}

.app-object-row {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--mode-row-radius, var(--radius-sm));
  box-shadow: var(--mode-row-shadow, none);
  color: var(--color-text);
  display: grid;
  gap: var(--space-2);
  grid-template-columns: auto minmax(0, 1fr) auto;
  min-height: var(--mode-row-min-height, 64px);
  padding: var(--mode-row-padding, var(--space-3));
  text-align: left;
  width: 100%;
}

button.app-object-row {
  cursor: pointer;
}

button.app-object-row:hover:not(:disabled) {
  border-color: var(--color-green-200);
  box-shadow: var(--shadow-sm);
}

.app-object-row--urgent {
  background: #fff7ed;
  border-color: #fed7aa;
}

.app-object-row--muted {
  background: var(--color-surface-muted);
}

.app-object-row-badge {
  align-items: center;
  background: var(--color-primary-soft);
  border: 1px solid var(--color-green-200);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  display: inline-flex;
  font-size: var(--font-size-xs);
  font-weight: 900;
  justify-content: center;
  min-width: 32px;
  padding: 4px 8px;
}

.app-object-row-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.app-object-row-copy strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 950;
  line-height: var(--line-title);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-object-row-copy small,
.app-object-row-copy em {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-style: normal;
  font-weight: 750;
  line-height: var(--line-title);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-object-row-action {
  align-items: center;
  display: flex;
  gap: var(--space-2);
  justify-content: flex-end;
}

.app-discovery-carousel {
  display: grid;
  gap: var(--space-2);
  grid-auto-columns: minmax(220px, 280px);
  grid-auto-flow: column;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  padding: 0 2px var(--space-2);
  scroll-snap-type: inline mandatory;
  scrollbar-width: thin;
}

.app-discovery-carousel > * {
  scroll-snap-align: start;
}

.app-compact-empty {
  align-items: center;
  background: rgba(255, 255, 255, 0.78);
  border: 1px dashed var(--color-border-strong);
  border-radius: var(--mode-row-radius, var(--radius-sm));
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  padding: var(--space-3);
}

.app-compact-empty > span:first-child {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.app-compact-empty strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 950;
}

.app-compact-empty small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 750;
  line-height: var(--line-title);
}

.app-scope-selector {
  align-items: center;
  display: flex;
  gap: var(--space-2);
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: thin;
}

.app-scope-selector button {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text-muted);
  display: inline-flex;
  flex: 0 0 auto;
  gap: var(--space-1);
  min-height: 36px;
  padding: 0 var(--space-3);
  white-space: nowrap;
}

.app-scope-selector button.active {
  background: var(--color-navy-900);
  border-color: var(--color-navy-900);
  color: #fff;
}

.app-scope-selector span,
.app-scope-selector small {
  font-size: var(--font-size-xs);
  font-weight: 900;
}

.app-primary-action {
  align-items: center;
  border-radius: var(--radius-sm);
  display: inline-flex;
  font-weight: 900;
  justify-content: center;
  min-height: var(--mode-button-min-height, 40px);
  padding: 0 var(--space-4);
}

.app-primary-action--primary {
  background: var(--color-primary);
  border: 1px solid var(--color-primary);
  color: var(--color-primary-fg);
}

.app-primary-action--secondary {
  background: var(--color-surface);
  border: 1px solid var(--color-border-strong);
  color: var(--color-text);
}

.app-primary-action--quiet {
  background: transparent;
  border: 1px solid transparent;
  color: var(--color-primary-strong);
}

.app-primary-action--danger {
  background: var(--color-danger);
  border: 1px solid var(--color-danger);
  color: #fff;
}

.app-visual-hero {
  background:
    linear-gradient(90deg, rgba(3, 10, 24, 0.97) 0%, rgba(4, 19, 40, 0.82) 43%, rgba(4, 19, 40, 0.18) 100%),
    var(--hero-image, var(--gradient-sport-hero));
  background-position: center;
  background-size: cover;
  border: 1px solid rgba(167, 227, 196, 0.34);
  border-radius: 30px;
  box-shadow:
    0 30px 78px rgba(3, 15, 33, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
  color: #fff;
  display: grid;
  min-height: 286px;
  overflow: hidden;
  padding: clamp(22px, 4vw, 42px);
  position: relative;
}

.app-visual-hero::before {
  background:
    linear-gradient(115deg, rgba(255, 255, 255, 0.13), transparent 32%),
    url("./assets/surface-court-lines-soft.png") left center / cover no-repeat;
  content: "";
  inset: 0;
  opacity: 0.25;
  pointer-events: none;
  position: absolute;
  mix-blend-mode: screen;
}

.app-visual-hero::after {
  background:
    radial-gradient(circle at 88% 72%, rgba(216, 244, 73, 0.18), transparent 22%),
    linear-gradient(180deg, transparent 42%, rgba(4, 11, 24, 0.42));
  content: "";
  inset: 0;
  pointer-events: none;
  position: absolute;
}

.app-visual-hero--light {
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.96), rgba(255, 255, 255, 0.74)),
    var(--hero-image, var(--gradient-surface));
  border-color: rgba(200, 210, 223, 0.68);
  box-shadow: var(--shadow-md);
  color: var(--color-text);
}

.app-visual-hero--light::before {
  opacity: 0.18;
}

.app-visual-hero--night {
  background:
    linear-gradient(90deg, rgba(3, 10, 24, 0.96) 0%, rgba(5, 34, 53, 0.7) 50%, rgba(6, 17, 38, 0.16)),
    var(--hero-image, var(--gradient-sport-hero));
}

.app-visual-hero-content,
.app-visual-hero-extra {
  position: relative;
  z-index: 1;
}

.app-visual-hero-content {
  align-content: center;
  display: grid;
  gap: var(--space-3);
  max-width: 720px;
}

.app-visual-eyebrow {
  color: var(--color-green-200);
  font-size: var(--font-size-xs);
  font-weight: 950;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.app-visual-hero--light .app-visual-eyebrow {
  color: var(--color-primary-strong);
}

.app-visual-hero h1 {
  color: inherit;
  font-size: clamp(2.25rem, 4.4vw, 4.35rem);
  font-weight: 950;
  letter-spacing: 0;
  line-height: 0.96;
  margin: 0;
  max-width: 11ch;
}

.app-visual-hero p {
  color: rgba(255, 255, 255, 0.84);
  font-size: var(--font-size-md);
  font-weight: 750;
  line-height: var(--line-body);
  margin: 0;
  max-width: 54ch;
}

.app-visual-hero--light p {
  color: var(--color-text-muted);
}

.app-visual-hero-actions,
.app-visual-hero-badges,
.app-visual-hero-meta {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.app-visual-hero-actions button,
.app-visual-hero-actions .app-primary-action {
  border-radius: var(--radius-pill);
  min-height: 46px;
  padding-inline: var(--space-5);
}

.app-visual-badge {
  align-items: center;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: var(--radius-pill);
  display: inline-flex;
  font-size: var(--font-size-xs);
  font-weight: 950;
  min-height: 30px;
  padding: 0 12px;
}

.app-visual-badge--success {
  background: rgba(22, 128, 78, 0.16);
  color: #c7f8dc;
}

.app-visual-badge--warning {
  background: rgba(217, 119, 6, 0.16);
  color: #ffedd5;
}

.app-visual-badge--info {
  background: rgba(37, 99, 235, 0.14);
  color: #dbeafe;
}

.app-visual-badge--neutral {
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.86);
}

.app-visual-badge--danger {
  background: rgba(220, 38, 38, 0.16);
  color: #fee2e2;
}

.app-shortcut-card {
  align-items: center;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(247, 252, 249, 0.9)),
    url("./assets/surface-court-lines-soft.png") right center / 360px auto no-repeat;
  border: 1px solid rgba(200, 210, 223, 0.72);
  border-radius: 22px;
  box-shadow: 0 16px 36px rgba(8, 18, 37, 0.08);
  color: var(--color-text);
  display: grid;
  gap: var(--space-3);
  grid-template-columns: 52px minmax(0, 1fr) auto;
  min-height: 104px;
  overflow: hidden;
  padding: var(--space-3);
  position: relative;
  text-align: left;
}

.app-shortcut-card::after {
  color: var(--color-primary-strong);
  content: "›";
  font-size: 26px;
  font-weight: 500;
  line-height: 1;
  opacity: 0.72;
}

.app-shortcut-card:hover:not(:disabled) {
  border-color: var(--color-green-200);
  box-shadow: 0 22px 46px rgba(8, 18, 37, 0.12);
  transform: translateY(-1px);
}

.app-shortcut-card.active {
  background:
    linear-gradient(145deg, rgba(6, 78, 59, 0.94), rgba(13, 148, 85, 0.9)),
    url("./assets/surface-court-lines-soft.png") center / cover no-repeat;
  border-color: rgba(167, 227, 196, 0.56);
  color: #fff;
}

.app-shortcut-image,
.app-shortcut-icon {
  align-items: center;
  background:
    radial-gradient(circle at 28% 20%, rgba(216, 244, 73, 0.28), transparent 38%),
    linear-gradient(145deg, rgba(231, 248, 240, 0.95), rgba(207, 239, 224, 0.9));
  border: 1px solid rgba(32, 185, 109, 0.16);
  border-radius: 19px;
  display: grid;
  height: 52px;
  justify-content: center;
  object-fit: cover;
  overflow: hidden;
  width: 52px;
}

.app-shortcut-icon {
  color: var(--color-primary);
  font-size: 26px;
}

.app-shortcut-card.active .app-shortcut-icon,
.app-shortcut-card.active .app-shortcut-image {
  background: rgba(255, 255, 255, 0.18);
}

.app-shortcut-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.app-shortcut-copy strong {
  color: inherit;
  font-size: var(--font-size-md);
  font-weight: 950;
  line-height: var(--line-title);
}

.app-shortcut-copy small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-shortcut-card.active .app-shortcut-copy small {
  color: rgba(255, 255, 255, 0.78);
}

.app-shortcut-badge {
  align-self: start;
  background: rgba(216, 244, 73, 0.18);
  border: 1px solid rgba(216, 244, 73, 0.34);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  padding: 4px 9px;
}

.app-metric-card {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(246, 250, 248, 0.94));
  border: 1px solid rgba(200, 210, 223, 0.72);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: 2px;
  min-height: 104px;
  padding: var(--space-4);
  position: relative;
}

.app-metric-icon {
  color: var(--color-primary-strong);
  position: absolute;
  right: var(--space-4);
  top: var(--space-4);
}

.app-metric-card strong {
  color: var(--color-text);
  font-size: var(--font-size-2xl);
  font-weight: 950;
  line-height: 1;
}

.app-metric-card span,
.app-metric-card small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 850;
}

.app-header-mark {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-md);
  box-shadow: 0 8px 18px rgba(8, 18, 37, 0.14);
}

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  color: var(--color-text);
  display: grid;
  place-items: center;
  cursor: pointer;
  position: relative;
  padding: 0;
  font-size: 18px;
}

.icon-btn:hover {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  color: var(--color-primary-strong);
}

.icon-btn svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
}

.app-bell-btn {
  position: relative;
}

.app-bell-btn.active {
  background: var(--color-primary-soft);
  border-color: var(--color-green-300);
  color: var(--color-primary-strong);
}

.app-bell-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  min-width: 18px;
  height: 18px;
  border-radius: 999px;
  background: var(--color-danger);
  border: 2px solid var(--color-surface);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
}

.app-notification-backdrop {
  background: transparent;
  border: 0;
  cursor: default;
  inset: 0;
  padding: 0;
  position: fixed;
  z-index: 70;
}

.app-notification-popover {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: 0 22px 60px rgba(8, 18, 37, 0.18);
  max-height: min(72vh, 640px);
  overflow: auto;
  padding: var(--space-3);
  position: absolute;
  right: 0;
  top: calc(100% + 10px);
  width: min(440px, calc(100vw - 32px));
  z-index: 80;
}

.app-notification-popover::before {
  background: var(--color-surface);
  border-left: 1px solid var(--color-border);
  border-top: 1px solid var(--color-border);
  content: "";
  height: 14px;
  position: absolute;
  right: 18px;
  top: -8px;
  transform: rotate(45deg);
  width: 14px;
}

.app-notification-popover .home-notification-panel {
  border: 0;
  box-shadow: none;
  margin: 0;
  padding: 0;
}

.icon-btn .badge-dot {
  position: absolute;
  top: 8px;
  right: 9px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-primary);
  border: 2px solid var(--color-surface);
}

.app-content {
  flex: 1;
  width: 100%;
  max-width: var(--mode-content-max-width, var(--content-max-width));
  margin: 0 auto;
  padding: var(--mode-page-padding, var(--space-5));
  padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + var(--mode-page-padding, var(--space-5)));
}

/* ----- Page header (used by inner pages instead of app-header) ----- */
.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--mode-section-gap, var(--space-4));
  padding-top: var(--space-1);
}

.page-header h1 {
  margin: 0;
  font-size: var(--font-size-2xl);
  font-weight: 950;
  color: var(--color-text);
  letter-spacing: 0;
  line-height: var(--line-tight);
}

.page-intro {
  margin: 4px 0 0;
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  max-width: 620px;
  font-weight: 700;
}

.page-header .ph-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.ph-icon-btn {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-pill);
  border: none;
  background: transparent;
  color: var(--color-text);
  display: grid;
  place-items: center;
  cursor: pointer;
  padding: 0;
}

.ph-icon-btn:hover {
  background: var(--color-surface-muted);
}

.ph-add-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-pill);
  border: none;
  background: var(--color-primary);
  color: #fff;
  display: grid;
  place-items: center;
  cursor: pointer;
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  padding: 0;
  transition: background 0.12s ease;
}

.ph-add-btn:hover {
  background: var(--color-primary-strong);
}

.ph-create-local-btn {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  box-shadow: var(--shadow-xs);
  color: var(--color-primary-strong);
  cursor: pointer;
  font-size: var(--font-size-sm);
  font-weight: 950;
  min-height: 40px;
  padding: 0 var(--space-3);
  transition: background 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease;
}

.ph-create-local-btn:hover {
  background: #f0fdf4;
  border-color: rgba(10, 85, 68, 0.28);
  box-shadow: var(--shadow-sm);
}

.compact-action {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  white-space: nowrap;
}

.compact-action svg {
  width: 18px;
  height: 18px;
}

.compact-action.primary {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-primary-fg);
}

.compact-action.primary:hover:not(:disabled) {
  background: var(--color-primary-strong);
  border-color: var(--color-primary-strong);
}

/* ----- Bottom navigation ----- */
.bottom-nav {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 100;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(58px, 1fr));
  padding: var(--space-2) var(--space-1) calc(var(--space-2) + env(safe-area-inset-bottom, 0px));
  background: rgba(255, 255, 255, 0.97);
  border-top: 1px solid rgba(203, 213, 225, 0.88);
  box-shadow: 0 -8px 24px rgba(15, 30, 61, 0.08);
  backdrop-filter: blur(14px);
}

.bottom-nav {
  background: rgba(255, 255, 255, 0.92);
  border-top-color: rgba(200, 210, 223, 0.9);
  box-shadow: 0 -10px 28px rgba(8, 18, 37, 0.08);
  backdrop-filter: blur(18px);
}

.bottom-nav-brand {
  display: none;
}

.bottom-nav-context,
.bottom-nav-group-label {
  display: none;
}

.bottom-nav-group {
  display: contents;
}

.bottom-nav button {
  background: transparent;
  border: none;
  color: var(--color-text-subtle);
  font-weight: 600;
  font-size: 11px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 6px 4px;
  border-radius: var(--radius-pill);
  min-height: 52px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.bottom-nav button {
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font-weight: 800;
}

.bottom-nav button:hover {
  background: var(--color-surface-muted);
  color: var(--color-text-muted);
}

.bottom-nav button:hover {
  background: rgba(232, 247, 239, 0.75);
}

.bottom-nav button.active {
  background: var(--color-primary-soft);
  color: var(--color-primary-strong);
  font-weight: 700;
  box-shadow: inset 0 0 0 1px rgba(168, 223, 191, 0.82);
}

.bottom-nav button.active {
  background: #ffffff;
  border-color: var(--color-green-200);
  font-weight: 900;
  box-shadow: var(--shadow-xs);
}

.bottom-nav button .nav-icon {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.bottom-nav button .nav-icon svg {
  width: 22px;
  height: 22px;
  display: block;
}

.app-tabs {
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 2px;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.app-tabs::-webkit-scrollbar {
  display: none;
}

.app-tabs button {
  flex: 0 0 auto;
  min-width: max-content;
  white-space: nowrap;
}

@media (min-width: 960px) {
  :root {
    --desktop-nav-width: 248px;
  }

  .app-content {
    max-width: min(var(--mode-content-max-width, var(--content-max-width)), calc(100vw - var(--desktop-nav-width) - 24px));
    margin-left: var(--desktop-nav-width);
    margin-right: 0;
    padding: var(--mode-desktop-page-padding, var(--mode-page-padding, var(--space-6)));
    padding-bottom: var(--mode-desktop-page-padding, var(--mode-page-padding, var(--space-6)));
  }

  .app-header {
    margin-left: var(--desktop-nav-width);
  }

  .bottom-nav {
    top: 0;
    right: auto;
    bottom: 0;
    width: var(--desktop-nav-width);
    display: flex;
    flex-direction: column;
    gap: 18px;
    padding: 26px 14px 18px;
    background:
      linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96)),
      var(--color-surface);
    border-top: none;
    border-right: 1px solid rgba(200, 210, 223, 0.88);
    box-shadow: 10px 0 36px rgba(8, 18, 37, 0.045);
  }

  .bottom-nav.is-management {
    background:
      linear-gradient(180deg, rgba(247, 252, 249, 0.98), rgba(255, 255, 255, 0.98)),
      var(--color-surface);
    border-right-color: rgba(180, 200, 190, 0.86);
    box-shadow: 10px 0 36px rgba(8, 18, 37, 0.055);
  }

  .bottom-nav.is-competition {
    background:
      linear-gradient(180deg, rgba(246, 252, 254, 0.98), rgba(255, 255, 255, 0.98)),
      var(--color-surface);
    border-right-color: rgba(170, 205, 220, 0.78);
  }

  .bottom-nav-brand {
    display: flex;
    flex-direction: column;
    gap: 5px;
    padding: 0 10px 18px;
    margin-bottom: -2px;
    border-bottom: 1px solid rgba(200, 210, 223, 0.72);
  }

  .bottom-nav.is-management .bottom-nav-brand {
    border-bottom-color: rgba(188, 205, 195, 0.78);
  }

  .bottom-nav-brand img {
    width: 152px;
    height: auto;
    display: block;
  }

  .bottom-nav-brand span {
    color: var(--color-text-subtle);
    font-size: var(--font-size-xs);
    font-weight: 700;
  }

  .bottom-nav.is-management .bottom-nav-brand span {
    color: var(--color-text-subtle);
  }

  .bottom-nav-context {
    align-self: flex-start;
    background: transparent;
    border: 0;
    border-radius: 0;
    color: var(--color-text-muted);
    display: inline-flex;
    font-size: 11px;
    font-weight: 900;
    line-height: 1;
    padding: 0;
  }

  .bottom-nav.is-management .bottom-nav-context {
    background: rgba(232, 247, 239, 0.9);
    border: 1px solid rgba(168, 223, 191, 0.9);
    border-radius: var(--radius-pill);
    border-color: rgba(168, 223, 191, 0.9);
    color: #0b5b41;
    padding: 5px 8px;
  }

  .bottom-nav.is-competition .bottom-nav-context {
    background: var(--color-cyan-100);
    border: 1px solid rgba(14, 116, 144, 0.18);
    border-radius: var(--radius-pill);
    border-color: rgba(14, 116, 144, 0.18);
    color: var(--color-cyan-600);
    padding: 5px 8px;
  }

  .bottom-nav-group {
    display: grid;
    gap: 5px;
  }

  .bottom-nav-group-label {
    color: var(--color-text-subtle);
    display: block;
    font-size: 10px;
    font-weight: 950;
    letter-spacing: 0;
    padding: 0 12px;
    text-transform: uppercase;
  }

  .bottom-nav.is-management .bottom-nav-group-label {
    color: var(--color-text-subtle);
  }

  .bottom-nav button {
    min-height: 46px;
    flex-direction: row;
    justify-content: flex-start;
    border-radius: 10px;
    padding: 10px 12px;
    font-size: var(--font-size-sm);
    position: relative;
  }

  .bottom-nav.is-management button {
    color: var(--color-text-muted);
  }

  .bottom-nav.is-management button:hover {
    background: rgba(232, 247, 239, 0.75);
    color: #0b5b41;
  }

  .bottom-nav.is-competition button:hover {
    background: rgba(230, 247, 251, 0.78);
    color: var(--color-cyan-600);
  }

  .bottom-nav.is-management .bottom-nav-group-account button,
  .bottom-nav.is-management .bottom-nav-group-account .bottom-nav-group-label {
    color: var(--color-text-muted);
  }

  .bottom-nav button span:last-child {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .bottom-nav button.active::before {
    content: "";
    position: absolute;
    left: 0;
    top: 10px;
    bottom: 10px;
    width: 3px;
    border-radius: 999px;
    background: var(--color-primary);
  }

  .bottom-nav button.active {
    background: #101827;
    border-color: rgba(16, 24, 39, 0.98);
    color: #ffffff;
    box-shadow: 0 10px 22px rgba(8, 18, 37, 0.13);
  }

  .bottom-nav.is-management button.active {
    background: #0b3d35;
    border-color: #0b3d35;
    color: #ffffff;
    box-shadow: 0 12px 28px rgba(7, 51, 43, 0.18);
  }

  .bottom-nav.is-competition button.active {
    background: var(--color-navy-800);
    border-color: var(--color-navy-800);
    color: #ffffff;
    box-shadow: 0 12px 28px rgba(8, 18, 37, 0.16);
  }

  .bottom-nav button.active::before {
    background: var(--color-primary);
  }
}

@media (max-width: 760px) {
  .app-shell {
    --mode-button-min-height: var(--density-touch-target);
    --mode-compact-button-min-height: 40px;
    --mode-input-min-height: var(--density-touch-target);
  }

  .app-page-header {
    display: grid;
    gap: var(--space-3);
  }

  .app-page-header h1,
  .app-action-panel h2 {
    font-size: var(--font-size-xl);
  }

  .app-page-header-actions,
  .app-action-panel-actions {
    width: 100%;
  }

  .app-page-header-actions > *,
  .app-action-panel-actions > * {
    flex: 1 1 auto;
  }

  .app-action-panel {
    padding: var(--space-3);
  }

  .app-object-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .app-object-row-badge,
  .app-object-row-action {
    justify-self: start;
  }

  .app-object-row-copy strong,
  .app-object-row-copy small,
  .app-object-row-copy em {
    white-space: normal;
  }

  .app-discovery-carousel {
    grid-auto-columns: minmax(244px, 82vw);
    margin-inline: calc(var(--space-3) * -1);
    padding-inline: var(--space-3);
  }

  .app-compact-empty {
    align-items: stretch;
    display: grid;
  }

  .app-content {
    padding: var(--mode-page-padding-mobile, var(--space-3));
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + var(--mode-page-padding-mobile, var(--space-3)));
  }

  .app-notification-backdrop {
    background: rgba(8, 18, 37, 0.42);
    cursor: pointer;
    z-index: 120;
  }

  .app-notification-popover {
    border-radius: 22px 22px 0 0;
    border-bottom: 0;
    bottom: 0;
    box-shadow: 0 -18px 56px rgba(8, 18, 37, 0.24);
    left: 0;
    max-height: min(84vh, 720px);
    padding: var(--space-4) var(--space-3) calc(var(--space-4) + env(safe-area-inset-bottom, 0px));
    position: fixed;
    right: 0;
    top: auto;
    width: auto;
    z-index: 130;
  }

  .app-notification-popover::before {
    background: var(--color-border);
    border: 0;
    border-radius: 999px;
    height: 4px;
    left: 50%;
    right: auto;
    top: 10px;
    transform: translateX(-50%);
    width: 46px;
  }

  .bottom-nav {
    display: flex;
    gap: 4px;
    overflow-x: auto;
    padding-left: 8px;
    padding-right: 8px;
    scrollbar-width: none;
  }

  .bottom-nav::-webkit-scrollbar {
    display: none;
  }

  .bottom-nav-group {
    display: contents;
  }

  .bottom-nav button {
    flex: 1 0 62px;
    min-width: 62px;
    min-height: 50px;
    padding: 5px 4px;
  }

  .bottom-nav button .nav-icon,
  .bottom-nav button .nav-icon svg {
    height: 20px;
    width: 20px;
  }
}

/* ----- Auth page ----- */
.auth-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: var(--space-4);
  background:
    radial-gradient(circle at 86% 92%, rgba(216, 244, 73, 0.24), transparent 20%),
    linear-gradient(135deg, #030914 0%, var(--color-navy-900) 46%, #073520 100%);
}

.auth-stage {
  background:
    linear-gradient(90deg, rgba(5, 12, 28, 0.9), rgba(5, 12, 28, 0.42)),
    var(--auth-image, var(--gradient-sport-hero));
  background-position: center;
  background-size: cover;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 34px;
  box-shadow: 0 34px 90px rgba(0, 0, 0, 0.36);
  display: grid;
  gap: clamp(24px, 5vw, 72px);
  grid-template-columns: minmax(0, 1.05fr) minmax(360px, 440px);
  max-width: 1180px;
  min-height: min(760px, calc(100vh - 48px));
  overflow: hidden;
  padding: clamp(28px, 5vw, 72px);
  position: relative;
  width: min(100%, 1180px);
}

.auth-stage::after {
  background:
    radial-gradient(circle at 10% 12%, rgba(255, 255, 255, 0.18), transparent 20%),
    linear-gradient(120deg, transparent 38%, rgba(255, 255, 255, 0.16) 38.4% 39%, transparent 39.4%);
  content: "";
  inset: 0;
  pointer-events: none;
  position: absolute;
}

.auth-brand-panel,
.auth-card {
  position: relative;
  z-index: 1;
}

.auth-brand-panel {
  align-content: center;
  color: #fff;
  display: grid;
  gap: var(--space-6);
  max-width: 540px;
}

.auth-brand-logo {
  filter: brightness(0) invert(1);
  width: 210px;
}

.auth-brand-panel h2 {
  color: #fff;
  font-size: clamp(2.4rem, 5vw, 4.6rem);
  font-weight: 950;
  letter-spacing: 0;
  line-height: 0.96;
  margin: 0;
  max-width: 10ch;
}

.auth-brand-panel h2::after {
  color: var(--color-green-400);
  content: " ";
}

.auth-brand-panel p {
  color: rgba(255, 255, 255, 0.82);
  font-size: var(--font-size-lg);
  font-weight: 700;
  line-height: var(--line-body);
  margin: 0;
  max-width: 38ch;
}

.auth-brand-panel ul {
  display: grid;
  gap: var(--space-3);
  list-style: none;
  margin: 0;
  padding: 0;
}

.auth-brand-panel li {
  align-items: center;
  backdrop-filter: blur(16px);
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: var(--radius-lg);
  display: grid;
  gap: 2px;
  max-width: 360px;
  padding: var(--space-3) var(--space-4);
}

.auth-brand-panel li span {
  color: #fff;
  font-size: var(--font-size-md);
  font-weight: 950;
}

.auth-brand-panel li small {
  color: rgba(255, 255, 255, 0.72);
  font-size: var(--font-size-sm);
  font-weight: 700;
}

.auth-card {
  width: min(420px, 100%);
  background: var(--color-surface);
  border: 1px solid rgba(168, 223, 191, 0.24);
  border-radius: 28px;
  justify-self: end;
  padding: clamp(24px, 4vw, 42px);
  box-shadow: 0 24px 70px rgba(5, 12, 28, 0.24);
}

.auth-card .auth-logo {
  width: min(240px, 78%);
  display: block;
  margin: 0 auto var(--space-4);
}

.auth-card h1 {
  margin: 0 0 var(--space-1);
  font-size: var(--font-size-xl);
  text-align: center;
  color: var(--color-text);
}

.auth-card .auth-sub {
  margin: 0 0 var(--space-5);
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  text-align: center;
}

.auth-divider {
  margin-top: var(--space-4);
  margin-bottom: var(--space-2);
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 700;
  text-transform: uppercase;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  height: 1px;
  flex: 1;
  background: var(--color-border);
}

.auth-divider span {
  white-space: nowrap;
}

.auth-google-btn {
  width: 100%;
  min-height: 46px;
  border: 1px solid var(--color-border-strong);
  background: #fff;
  color: #111827;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-weight: 700;
}

.auth-google-btn:hover:not(:disabled) {
  background: #f9fafb;
}

.auth-actions {
  margin-top: var(--space-3);
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-2);
}

.auth-card input {
  min-height: 52px;
}

.auth-card button.primary,
.auth-card button.secondary,
.auth-google-btn {
  border-radius: 14px;
  min-height: 52px;
}

.setup-overview {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: linear-gradient(180deg, #f8fbff 0%, #ffffff 100%);
  padding: 12px;
  margin-bottom: 12px;
}

.setup-overview-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.setup-overview-title {
  margin: 0;
  font-weight: 800;
  color: var(--color-text);
}

.setup-overview-subtitle {
  margin: 2px 0 0 0;
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
}

.setup-progress-chip {
  border-radius: 999px;
  border: 1px solid var(--color-border);
  padding: 4px 10px;
  font-size: var(--font-size-xs);
  font-weight: 800;
  background: #f8fafc;
  color: var(--color-text-muted);
}

.setup-progress-chip.ready {
  background: #ecfdf5;
  color: #047857;
  border-color: #a7f3d0;
}

.setup-progress-chip.pending {
  background: #fff7ed;
  color: #9a3412;
  border-color: #fed7aa;
}

.setup-progress-bar {
  margin-top: 10px;
  height: 8px;
  border-radius: 999px;
  background: #e2e8f0;
  overflow: hidden;
}

.setup-progress-bar span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #22c55e 0%, #16a34a 100%);
}

.setup-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}

.setup-kpi {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: #fff;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.setup-kpi strong {
  font-size: var(--font-size-lg);
  color: var(--color-text);
}

.setup-kpi span {
  font-size: var(--font-size-xs);
  color: var(--color-text-subtle);
}

.setup-stage-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 10px;
}

.setup-stage {
  min-height: 56px;
  text-align: left;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: #fff;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.setup-stage span {
  font-size: var(--font-size-sm);
  color: var(--color-text);
}

.setup-stage strong {
  font-size: var(--font-size-xs);
}

.setup-stage.ok {
  border-color: #86efac;
  background: #f0fdf4;
}

.setup-stage.ok strong {
  color: #15803d;
}

.setup-stage.todo {
  border-color: #fcd34d;
  background: #fffbeb;
}

.setup-stage.todo strong {
  color: #b45309;
}

@media (max-width: 720px) {
  .setup-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .setup-stage-list {
    grid-template-columns: 1fr;
  }
}

.tournament-panel-kpis {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 12px;
}

.tournament-panel-kpi {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 10px;
  background: #fff;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tournament-panel-kpi strong {
  font-size: var(--font-size-lg);
  color: var(--color-text);
}

.tournament-panel-kpi span {
  font-size: var(--font-size-xs);
  color: var(--color-text-subtle);
}

.match-status-legend {
  align-items: center;
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin: 0 0 var(--space-3);
  padding: var(--space-2);
}

.tournament-overview-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-2);
  margin-top: var(--space-3);
}

.tournament-overview-kpi {
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-2);
}

.tournament-overview-kpi strong {
  display: block;
  color: var(--color-text);
  font-size: var(--font-size-lg);
  line-height: 1.1;
}

.tournament-overview-kpi span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
}

.tournament-next-action {
  align-items: flex-start;
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-top: var(--space-3);
  text-align: left;
  width: 100%;
}

.tournament-next-action span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.tournament-next-action strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
}

.tournament-phase-flow {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin-top: var(--space-3);
}

.tournament-phase-flow button {
  align-items: flex-start;
  background: #fff;
  border: 1px solid var(--color-border);
  color: var(--color-text);
  display: grid;
  gap: 2px;
  min-height: 64px;
  padding: var(--space-2);
  text-align: left;
}

.tournament-phase-flow button.active {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  box-shadow: 0 0 0 1px rgba(22, 163, 74, 0.14);
}

.tournament-phase-flow span {
  font-size: var(--font-size-sm);
  font-weight: 800;
}

.tournament-phase-flow small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
}

.tournament-operational-cockpit {
  background:
    linear-gradient(135deg, rgba(4, 16, 31, 0.96), rgba(8, 43, 41, 0.86)),
    url("./assets/pdark-competitions-trophy-desktop-hero.png") right center / cover no-repeat;
  border: 1px solid rgba(74, 222, 128, 0.18);
  border-radius: 22px;
  box-shadow: 0 18px 48px rgba(2, 8, 19, 0.22);
  color: #ffffff;
  display: grid;
  gap: var(--space-3);
  grid-template-columns: minmax(0, 1.25fr) minmax(260px, 0.75fr);
  margin-bottom: var(--space-3);
  overflow: hidden;
  padding: var(--space-4);
  position: relative;
}

.tournament-operational-cockpit::before {
  background: linear-gradient(90deg, rgba(2, 8, 19, 0.82), rgba(2, 8, 19, 0.3));
  content: "";
  inset: 0;
  position: absolute;
}

.tournament-operational-cockpit > * {
  position: relative;
  z-index: 1;
}

.tournament-operational-copy {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
}

.tournament-operational-copy span,
.tournament-role-chip {
  color: #86efac;
  font-size: var(--font-size-xs);
  font-weight: 950;
  letter-spacing: 0;
  text-transform: uppercase;
}

.tournament-operational-copy h2 {
  color: #ffffff;
  font-size: clamp(1.35rem, 3vw, 2.25rem);
  line-height: var(--line-title);
  margin: 0;
  max-width: 16ch;
}

.tournament-operational-copy p {
  color: rgba(226, 232, 240, 0.86);
  font-size: var(--font-size-sm);
  font-weight: 800;
  line-height: var(--line-normal);
  margin: 0;
  max-width: 66ch;
}

.tournament-operational-side {
  align-content: start;
  display: grid;
  gap: var(--space-2);
}

.tournament-role-chip {
  background: rgba(34, 197, 94, 0.14);
  border: 1px solid rgba(74, 222, 128, 0.28);
  border-radius: var(--radius-pill);
  justify-self: start;
  padding: 5px 10px;
}

.tournament-operational-metrics {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.tournament-operational-metrics article {
  background: rgba(8, 20, 36, 0.72);
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 16px;
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: var(--space-2);
}

.tournament-operational-metrics strong {
  color: #ffffff;
  font-size: var(--font-size-lg);
  font-weight: 950;
  line-height: 1;
}

.tournament-operational-metrics span {
  color: rgba(203, 213, 225, 0.82);
  font-size: var(--font-size-xs);
  font-weight: 820;
}

.tournament-operational-action {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  grid-column: 1 / -1;
}

.tournament-operational-action > button {
  min-width: 220px;
}

.tournament-operational-action > div {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.tournament-operational-action > div button {
  background: rgba(15, 28, 46, 0.88);
  border-color: rgba(255, 255, 255, 0.14);
  color: rgba(241, 245, 249, 0.9);
}

.tournament-operational-blockers {
  background: rgba(8, 20, 36, 0.72);
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 16px;
  color: rgba(226, 232, 240, 0.88);
  display: grid;
  gap: var(--space-2);
  grid-column: 1 / -1;
  padding: var(--space-3);
}

.tournament-operational-blockers.has-blockers {
  border-color: rgba(250, 204, 21, 0.24);
}

.tournament-operational-blockers.ready {
  border-color: rgba(74, 222, 128, 0.26);
}

.tournament-operational-blockers strong {
  color: #ffffff;
  font-size: var(--font-size-sm);
  font-weight: 950;
}

.tournament-operational-blockers ul {
  display: grid;
  gap: 5px;
  margin: 0;
  padding-left: 18px;
}

.tournament-operational-blockers li,
.tournament-operational-blockers p {
  color: rgba(203, 213, 225, 0.86);
  font-size: var(--font-size-xs);
  font-weight: 800;
  line-height: var(--line-normal);
  margin: 0;
}

@media (max-width: 760px) {
  .tournament-operational-cockpit {
    background-position: center top;
    border-radius: 18px;
    gap: var(--space-3);
    grid-template-columns: 1fr;
    padding: var(--space-3);
  }

  .tournament-operational-cockpit::before {
    background: linear-gradient(180deg, rgba(2, 8, 19, 0.9), rgba(2, 8, 19, 0.58));
  }

  .tournament-operational-copy h2 {
    font-size: 1.55rem;
    max-width: none;
  }

  .tournament-operational-copy p {
    max-width: none;
  }

  .tournament-operational-side {
    gap: var(--space-2);
  }

  .tournament-operational-action {
    align-items: stretch;
    display: grid;
    grid-template-columns: 1fr;
  }

  .tournament-operational-action > button {
    min-width: 0;
    width: 100%;
  }

  .tournament-operational-action > div {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .tournament-operational-action > div button {
    min-width: 0;
    padding-inline: 8px;
  }

  .tournament-operational-blockers {
    padding: var(--space-2);
  }
}

.tournament-share-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-2);
}

.tournament-share-actions button {
  min-height: 38px;
}

.tournament-public-event {
  display: grid;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
}

.competition-public-topbar {
  align-items: center;
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
}

.competition-public-topbar button {
  min-height: 38px;
}

.league-public-page-title {
  align-items: center;
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  min-width: 0;
}

.league-public-page-title div {
  min-width: 0;
}

.league-public-page-title span:first-child {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.league-public-page-title h1 {
  color: var(--color-text);
  font-size: var(--font-size-2xl);
  font-weight: 950;
  letter-spacing: 0;
  line-height: var(--line-tight);
  margin: 2px 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.competition-public-context-note {
  color: var(--color-text-muted);
  font-size: var(--font-size-sm);
  font-weight: 650;
  margin: 6px 0 0;
}

.tournament-public-hero {
  align-items: stretch;
  background: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: var(--space-4);
  grid-template-columns: minmax(0, 1fr) minmax(260px, 380px);
  overflow: hidden;
  padding: var(--space-4);
}

.tournament-public-copy {
  align-content: start;
  display: grid;
  gap: var(--space-3);
  min-width: 0;
}

.tournament-public-title-row,
.tournament-public-meta,
.tournament-public-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.tournament-public-title-row > span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.tournament-public-title-row .tournament-public-personal-status {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 950;
  padding: 6px 10px;
  text-transform: none;
}

.tournament-public-title-row .tournament-public-personal-status.success {
  background: var(--color-primary-soft);
  border-color: rgba(12, 118, 74, 0.28);
  color: var(--color-primary-strong);
}

.tournament-public-title-row .tournament-public-personal-status.warning {
  background: rgba(217, 119, 6, 0.1);
  border-color: rgba(217, 119, 6, 0.26);
  color: #92400e;
}

.tournament-public-title-row .tournament-public-personal-status.danger {
  background: rgba(220, 38, 38, 0.1);
  border-color: rgba(220, 38, 38, 0.24);
  color: var(--color-danger);
}

.tournament-public-copy h2 {
  color: var(--color-text);
  font-size: var(--font-size-3xl);
  font-weight: 950;
  letter-spacing: 0;
  line-height: var(--line-tight);
  margin: 0;
}

.tournament-public-meta span {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  font-size: var(--font-size-xs);
  font-weight: 850;
  padding: 7px 10px;
}

.competition-public-action-rail {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.competition-public-action-rail button {
  align-content: start;
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  display: grid;
  gap: 4px;
  min-height: 104px;
  padding: var(--space-2);
  text-align: left;
}

.competition-public-action-rail button:hover {
  border-color: rgba(21, 128, 61, 0.34);
  box-shadow: var(--shadow-sm);
}

.competition-public-action-rail span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
}

.competition-public-action-rail strong {
  color: var(--color-text);
  font-size: var(--font-size-lg);
  font-weight: 950;
  line-height: 1.05;
}

.competition-public-action-rail small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 750;
  line-height: var(--line-normal);
}

.tournament-public-main-cta {
  align-items: flex-start;
  display: grid;
  gap: 1px;
  min-width: min(100%, 240px);
  text-align: left;
}

.tournament-public-main-cta small {
  color: rgba(255, 255, 255, 0.82);
  font-size: var(--font-size-xs);
  font-weight: 750;
}

.tournament-public-media {
  background: var(--color-navy-900);
  border-radius: var(--radius-md);
  min-height: 260px;
  overflow: hidden;
  position: relative;
}

.tournament-public-media img {
  display: block;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.tournament-public-media > div {
  align-content: center;
  color: #ffffff;
  display: grid;
  gap: var(--space-2);
  height: 100%;
  justify-items: center;
  min-height: 260px;
  text-align: center;
}

.tournament-public-media > div span {
  align-items: center;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 999px;
  display: inline-flex;
  font-size: var(--font-size-2xl);
  font-weight: 950;
  height: 88px;
  justify-content: center;
  width: 88px;
}

.tournament-public-media > div small {
  color: rgba(255, 255, 255, 0.74);
  font-size: var(--font-size-xs);
  font-weight: 850;
}

.tournament-public-nav {
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  display: flex;
  gap: var(--space-1);
  overflow-x: auto;
  padding: 4px;
  scroll-padding-inline: var(--space-2);
  scroll-snap-type: x proximity;
  scrollbar-width: none;
}

.tournament-public-nav::-webkit-scrollbar {
  display: none;
}

.tournament-public-nav button {
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  color: var(--color-text-subtle);
  flex: 0 0 auto;
  font-size: var(--font-size-xs);
  font-weight: 950;
  min-height: 36px;
  padding: 7px 12px;
  scroll-snap-align: start;
  white-space: nowrap;
}

.tournament-public-nav button.active {
  background: var(--color-navy-900);
  border-color: var(--color-navy-900);
  color: #ffffff;
}

.tournament-public-categories {
  display: grid;
  gap: var(--space-2);
}

.tournament-public-category-rail {
  display: grid;
  gap: var(--space-2);
  grid-auto-columns: minmax(220px, 280px);
  grid-auto-flow: column;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: thin;
}

.tournament-public-category-rail button {
  align-content: start;
  background: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  display: grid;
  gap: 4px;
  min-height: 142px;
  padding: var(--space-3);
  text-align: left;
}

.tournament-public-category-rail button.active {
  border-color: var(--color-green-500);
  box-shadow: 0 0 0 1px rgba(22, 163, 74, 0.18), var(--shadow-sm);
}

.tournament-public-category-rail span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 850;
}

.tournament-public-category-rail strong {
  color: var(--color-text);
  font-size: var(--font-size-md);
  font-weight: 950;
  line-height: var(--line-title);
}

.tournament-public-category-rail small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 750;
}

.tournament-public-category-rail em {
  align-self: end;
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-style: normal;
  font-weight: 950;
  margin-top: var(--space-2);
}

.competition-public-list-section {
  display: grid;
  gap: var(--space-2);
}

.competition-public-search-row {
  align-items: end;
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(220px, 420px) auto;
  justify-content: start;
  margin-bottom: var(--space-2);
}

.competition-public-search-row label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.competition-public-search-row label span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.competition-public-search-row input {
  min-height: 40px;
  width: 100%;
}

.league-public-class-filter {
  align-items: end;
  background: linear-gradient(180deg, #ffffff, rgba(248, 250, 252, 0.92));
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(0, 1fr) minmax(180px, 240px);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
}

.league-public-class-filter > div:first-child {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.league-public-class-filter span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.league-public-class-filter strong {
  color: var(--color-text);
  font-size: var(--font-size-lg);
  font-weight: 950;
  line-height: var(--line-title);
}

.league-public-class-filter small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 750;
}

.league-public-class-filter label {
  display: grid;
  gap: 6px;
}

.league-public-class-filter label span {
  color: var(--color-text-subtle);
}

.league-public-class-filter select {
  min-height: 40px;
}

.tournament-public-class-filter {
  grid-template-columns: minmax(0, 1fr) minmax(220px, 320px);
}

.tournament-public-class-filter label {
  justify-self: end;
  width: min(320px, 100%);
}

.league-public-class-chip-rail {
  display: none;
  gap: var(--space-1);
  grid-column: 1 / -1;
  overflow-x: auto;
  padding-bottom: 2px;
  scroll-padding-inline: var(--space-1);
  scroll-snap-type: x proximity;
  scrollbar-width: none;
}

.league-public-class-chip-rail.is-hidden {
  display: none;
}

.league-public-class-chip-rail::-webkit-scrollbar {
  display: none;
}

.league-public-class-chip-rail button {
  align-items: center;
  background: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text-subtle);
  display: inline-flex;
  flex: 0 0 auto;
  font-size: var(--font-size-xs);
  gap: 7px;
  font-weight: 950;
  min-height: 32px;
  padding: 6px 12px;
  scroll-snap-align: start;
  white-space: nowrap;
}

.league-public-class-chip-rail button.active {
  background: var(--color-navy-900);
  border-color: var(--color-navy-900);
  color: #ffffff;
}

.league-public-class-chip-rail button span {
  background: var(--color-surface-muted);
  border-radius: var(--radius-pill);
  color: inherit;
  font-size: 11px;
  font-weight: 950;
  line-height: 1;
  padding: 4px 7px;
  text-transform: none;
}

.league-public-class-chip-rail button.active span {
  background: rgba(255, 255, 255, 0.16);
}

.competition-public-list-toolbar {
  align-items: end;
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(220px, 360px);
}

.competition-public-list-toolbar label {
  color: var(--color-text-subtle);
  display: grid;
  font-size: var(--font-size-xs);
  font-weight: 950;
  gap: 6px;
  text-transform: uppercase;
}

.competition-public-list-toolbar input {
  box-sizing: border-box;
  width: 100%;
}

.league-public-member-status {
  align-items: center;
  background: rgba(22, 163, 74, 0.08);
  border: 1px solid rgba(22, 163, 74, 0.22);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  display: inline-flex;
  gap: var(--space-2);
  justify-self: start;
  max-width: 100%;
  padding: 7px 10px;
}

.league-public-member-status span {
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.league-public-member-status strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 950;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.league-public-member-status small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 750;
  line-height: var(--line-compact);
}

.competition-public-person-list {
  background: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  display: grid;
  overflow: hidden;
}

.competition-public-person-row {
  align-items: center;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
  min-height: 58px;
  padding: var(--space-2) var(--space-3);
}

.competition-public-person-row:last-child {
  border-bottom: 0;
}

.competition-public-person-row div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.competition-public-person-row strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 900;
  line-height: var(--line-title);
}

.competition-public-person-row span,
.competition-public-person-row small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 750;
}

.competition-public-person-row small {
  flex: 0 0 auto;
}

.tournament-public-sticky-cta {
  display: none;
}

.publishing-kit {
  align-items: center;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.98)),
    radial-gradient(circle at top left, rgba(22, 163, 74, 0.12), transparent 32%);
  border: 1px solid rgba(148, 163, 184, 0.34);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(220px, 1fr) repeat(3, auto);
  margin-top: var(--space-3);
  padding: var(--space-3);
}

.publishing-kit > div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.publishing-kit span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.publishing-kit strong {
  color: var(--color-text);
  font-size: var(--font-size-md);
  font-weight: 950;
  line-height: var(--line-title);
}

.publishing-kit small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
  line-height: var(--line-normal);
}

.publishing-kit-actions {
  align-items: center;
  display: contents;
}

.publishing-kit button {
  min-height: 38px;
  white-space: nowrap;
}

.player-next-match-card {
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-2);
  margin-top: var(--space-3);
  padding: var(--space-3);
}

.player-next-match-card > span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.player-next-match-card > strong {
  color: var(--color-text);
}

.player-next-match-card > small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
}

.organizer-alert-card {
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-2);
  margin-top: var(--space-3);
  padding: var(--space-3);
}

.organizer-alert-card > span {
  color: #c2410c;
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.organizer-alert-card > strong {
  color: var(--color-text);
}

.organizer-alert-card > small,
.organizer-alert-item small {
  color: #9a3412;
  font-size: var(--font-size-xs);
}

.organizer-alert-card > button,
.organizer-alert-item button {
  justify-self: flex-start;
  min-height: 34px;
}

.organizer-alert-item {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: space-between;
}

.organizer-pending-center,
.tournament-completion-guard {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-3);
  margin-top: var(--space-3);
  padding: var(--space-3);
}

.organizer-pending-center {
  background: #f8fafc;
}

.organizer-pending-head {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: space-between;
}

.organizer-pending-head > div,
.tournament-completion-guard > div {
  display: grid;
  gap: 2px;
}

.organizer-pending-head span,
.tournament-completion-guard span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.organizer-pending-head strong,
.tournament-completion-guard strong {
  color: var(--color-text);
}

.organizer-pending-head button {
