.match-input-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.tournament-score-row {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) 96px 96px;
  width: 100%;
}

.tournament-score-row > .subtle {
  align-self: center;
  font-weight: 800;
}

.tournament-score-tiebreak-row {
  align-items: center;
  display: grid;
  gap: 8px;
  grid-column: 1 / -1;
  grid-template-columns: minmax(120px, 1fr) 96px 96px;
  padding-left: 10px;
}

.tournament-score-tiebreak-row .match-score-input,
.tournament-score-super-row .match-score-input {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
}

.match-score-summary {
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 800;
  margin: 0;
  padding: 4px 9px;
}

.match-score-disclosure {
  border-top: 1px solid var(--color-border);
  display: grid;
  gap: var(--space-2);
  padding-top: var(--space-2);
}

.match-score-disclosure summary {
  align-items: center;
  color: var(--color-text);
  cursor: pointer;
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
  list-style: none;
  min-height: 34px;
}

.match-score-disclosure summary::-webkit-details-marker {
  display: none;
}

.match-score-disclosure summary span {
  font-size: var(--font-size-sm);
  font-weight: 900;
}

.match-score-disclosure summary small {
  color: var(--color-text-muted);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.match-admin-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: 0;
  padding-top: 0;
}

.match-admin-actions button {
  min-height: 34px;
}

.match-score-input {
  width: 80px;
}

@media (max-width: 900px) {
  .publishing-kit {
    grid-template-columns: 1fr;
  }

  .tournament-public-hero {
    grid-template-columns: 1fr;
    padding: var(--space-3);
  }

  .tournament-public-media {
    min-height: 220px;
    order: -1;
  }

  .tournament-public-copy h2 {
    font-size: var(--font-size-2xl);
  }

  .publishing-kit-actions {
    display: grid;
    gap: var(--space-2);
  }

  .publishing-kit button {
    width: 100%;
  }

  .tournament-class-switcher {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .competition-scope-selector,
  .competition-operational-queue-head,
  .competition-header {
    align-items: stretch;
    flex-direction: column;
  }

  .competition-filter-stack-priority {
    grid-template-columns: 1fr;
  }

  .responsive-filter-inline {
    display: none;
  }

  .responsive-filter-trigger {
    display: grid;
  }

  .responsive-filter-sheet-body .competition-filter-stack {
    margin-bottom: 0;
  }

  .competition-header-actions {
    justify-content: flex-start;
  }

  .competition-scope-selector select {
    max-width: none;
    min-width: 0;
    width: 100%;
  }

  .competition-operational-queue-grid button {
    align-items: start;
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .competition-operational-queue-grid small {
    grid-column: 2;
    justify-self: start;
    text-align: left;
  }

  .competition-operational-queue-grid em {
    grid-column: 1 / -1;
    justify-self: stretch;
    text-align: center;
  }

  .tournament-organizer-queue-head {
    align-items: stretch;
    flex-direction: column;
  }

  .tournament-organizer-task-row {
    align-items: start;
    gap: var(--space-2);
    grid-template-columns: 1fr;
  }

  .tournament-organizer-task-impact {
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    padding: var(--space-2);
  }

  .tournament-organizer-task-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    justify-content: stretch;
    width: 100%;
  }

  .tournament-organizer-task-actions button {
    width: 100%;
  }

  .tournament-organizer-drawer-backdrop {
    align-items: flex-end;
    padding: 0;
  }

  .tournament-organizer-drawer {
    border-radius: var(--radius-lg) var(--radius-lg) 0 0;
    max-height: 86vh;
    max-width: none;
    width: 100%;
  }

  .tournament-organizer-drawer header,
  .tournament-organizer-drawer footer {
    padding: var(--space-3);
  }

  .tournament-games-card {
    padding: var(--space-3);
  }

  .tournament-public-match-summary-head {
    display: grid;
  }

  .tournament-public-match-row {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .tournament-public-match-row em {
    justify-self: flex-start;
  }

  .tournament-chat-head,
  .tournament-chat-message-meta,
  .tournament-chat-compose {
    align-items: stretch;
    display: grid;
    gap: var(--space-2);
  }

  .tournament-chat-head-actions,
  .tournament-chat-message-actions {
    justify-content: stretch;
  }

  .tournament-chat-head-actions button,
  .tournament-chat-message-actions button,
  .tournament-chat-compose button {
    flex: 1;
  }

  .tournament-chat-list {
    max-height: none;
  }

  .tournament-games-card.public-reader .tournament-bracket-heading,
  .tournament-games-card.public-reader .tournament-phase-section {
    display: none;
  }

  .tournament-court-agenda-head {
    display: grid;
  }

  .tournament-court-agenda-grid {
    grid-template-columns: 1fr;
  }

  .tournament-podium-head {
    display: grid;
  }

  .tournament-podium-grid {
    grid-template-columns: 1fr;
  }

  .my-matches-head {
    display: grid;
  }

  .my-matches-tools {
    display: grid;
    grid-template-columns: 1fr;
    justify-content: stretch;
  }

  .my-matches-tools > * {
    justify-content: center;
    width: 100%;
  }

  .my-match-main {
    align-items: stretch;
    grid-template-columns: minmax(0, 1fr);
  }

  .my-match-summary {
    align-items: flex-start;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  .my-match-summary em {
    justify-self: flex-start;
  }

  .my-match-context {
    display: grid;
  }

  .my-match-actions {
    display: grid;
    grid-template-columns: 1fr;
    justify-content: stretch;
  }

  .my-match-actions button {
    justify-content: center;
    min-height: 44px;
    padding-inline: var(--space-3);
    width: 100%;
  }

  .my-match-result-tools {
    grid-template-columns: 1fr;
  }

  .my-match-result-tools > button {
    width: 100%;
  }

  .match-confirmation-actions,
  .match-confirmation-response {
    align-items: stretch;
    display: grid;
    grid-template-columns: 1fr;
  }

  .match-confirmation-actions button,
  .match-confirmation-response button,
  .match-confirmation-status {
    justify-content: center;
    text-align: center;
    width: 100%;
  }

  .match-operational-state {
    align-items: stretch;
    display: grid;
  }

  .match-operational-state strong {
    text-align: left;
  }

  .match-row-main {
    align-items: stretch;
    grid-template-columns: minmax(0, 1fr);
  }

  .match-row-context {
    display: grid;
    justify-content: stretch;
  }

  .match-row-context > * {
    width: 100%;
  }

  .match-score-disclosure summary {
    align-items: flex-start;
    display: grid;
  }

  .match-admin-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .match-admin-actions button {
    justify-content: center;
    width: 100%;
  }

  .tournament-score-row,
  .tournament-score-tiebreak-row {
    grid-template-columns: minmax(92px, 1fr) minmax(70px, 84px) minmax(70px, 84px);
  }

  .tournament-panel-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tournament-overview-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tournament-phase-flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .my-match-result-tools {
    grid-template-columns: minmax(0, 1fr);
  }
}

.auth-readonly {
  background: var(--color-surface-muted);
  color: var(--color-text-muted);
}

/* ----- Generic primitives ----- */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--mode-card-radius, var(--radius-md));
  padding: var(--mode-card-padding, var(--space-5));
  box-shadow: var(--mode-surface-shadow, var(--shadow-sm));
}

.card,
.place-booking-panel,
.academy-workspace-card,
.academy-workspace-row,
.place-management-cockpit,
.place-operations-board {
  box-shadow: var(--mode-surface-shadow, var(--shadow-sm));
}

.card + .card {
  margin-top: var(--space-3);
}

.section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 0 var(--space-3);
}

.section-title h2 {
  margin: 0;
  font-size: var(--font-size-md);
  font-weight: 950;
  line-height: var(--line-title);
  color: var(--color-text);
}

.section-title .link {
  font-weight: 850;
  font-size: var(--font-size-xs);
  color: var(--color-primary-strong);
  background: none;
  border: none;
  cursor: pointer;
}

.subtle {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 650;
}

.feedback {
  margin: var(--space-3) 0 0;
  padding: 10px var(--space-3);
  border-radius: var(--radius-sm);
  background: #fff7ed;
  border: 1px solid #fed7aa;
  color: #9a3412;
  font-size: var(--font-size-sm);
  font-weight: 800;
}

.feedback.success {
  background: var(--color-status-open-bg);
  border-color: var(--color-green-200);
  color: var(--color-status-open-fg);
}

.feedback.error {
  background: #fee2e2;
  border-color: #fecaca;
  color: #991b1b;
}

.app-toast-stack {
  position: fixed;
  top: calc(var(--space-4) + env(safe-area-inset-top, 0px));
  right: var(--space-4);
  z-index: 10000;
  display: grid;
  gap: var(--space-2);
  width: min(420px, calc(100vw - (var(--space-4) * 2)));
  pointer-events: none;
}

.app-toast {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto;
  gap: var(--space-2);
  align-items: start;
  padding: 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.16);
  color: var(--color-text);
  pointer-events: auto;
}

.app-toast-marker {
  width: 8px;
  min-height: 100%;
  border-radius: 999px;
  background: var(--color-primary);
}

.app-toast-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.app-toast-copy strong {
  font-size: var(--font-size-sm);
  line-height: 1.2;
}

.app-toast-copy small {
  color: var(--color-text-muted);
  font-size: var(--font-size-sm);
  font-weight: 750;
  line-height: 1.35;
}

.app-toast button {
  min-width: 36px;
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 999px;
  background: #f3f6f8;
  color: var(--color-text-muted);
  font-size: 1rem;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
}

.app-shell--management .app-sheet.entity-drawer,
.app-shell--management .app-overlay-actions {
  background:
    linear-gradient(180deg, rgba(7, 18, 32, 0.98), rgba(4, 12, 24, 0.98)),
    var(--pdark-surface-texture);
  border-color: rgba(166, 198, 229, 0.16);
  color: var(--pdark-text-main);
}

.app-shell--management .app-overlay-actions {
  border-top-color: rgba(166, 198, 229, 0.16);
  box-shadow: 0 -18px 38px rgba(0, 0, 0, 0.22);
}

.app-toast--success .app-toast-marker {
  background: var(--color-primary-strong);
}

.app-toast--error .app-toast-marker {
  background: #dc2626;
}

.app-toast--info .app-toast-marker {
  background: #2563eb;
}

.app-toast--loading .app-toast-marker {
  background: #f59e0b;
}

@media (max-width: 720px) {
  .app-toast-stack {
    top: auto;
    right: var(--space-3);
    bottom: calc(78px + env(safe-area-inset-bottom, 0px));
    left: var(--space-3);
    width: auto;
  }

  .app-toast {
    border-radius: var(--radius-lg);
  }
}

label {
  display: block;
  margin: var(--space-3) 0 var(--space-1);
  color: var(--color-text-muted);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

input,
select,
textarea {
  width: 100%;
  min-height: var(--mode-input-min-height, var(--density-touch-target));
  padding: 10px 13px;
  border: 1px solid var(--color-border-strong);
  border-radius: var(--mode-row-radius, var(--radius-md));
  background: var(--color-surface);
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 750;
  transition: background 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease;
}

input::placeholder,
textarea::placeholder {
  color: #8a98aa;
  font-weight: 650;
}

input:focus,
select:focus,
textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: var(--shadow-focus);
}

textarea {
  min-height: 88px;
  resize: vertical;
}

button {
  border: 1px solid var(--color-border-strong);
  background: var(--color-surface);
  color: var(--color-text);
  border-radius: var(--mode-row-radius, var(--radius-sm));
  min-height: var(--mode-button-min-height, 40px);
  padding: 9px 14px;
  font-weight: 850;
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease, transform 0.08s ease;
}

button:focus-visible,
a:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}

button:hover:not(:disabled) {
  background: var(--color-surface-muted);
  border-color: var(--color-border-strong);
  box-shadow: var(--shadow-xs);
}

button:active:not(:disabled) {
  transform: translateY(1px);
}

button.primary {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-primary-fg);
  box-shadow: 0 8px 18px rgba(22, 128, 78, 0.16);
}

button.primary:hover:not(:disabled) {
  background: var(--color-primary-strong);
  border-color: var(--color-primary-strong);
  box-shadow: 0 10px 22px rgba(21, 94, 50, 0.2);
}

button.secondary {
  background: var(--color-surface);
  border-color: var(--color-border-strong);
  color: var(--color-text);
  box-shadow: var(--shadow-xs);
}

button.secondary:hover:not(:disabled) {
  background: var(--color-surface-muted);
  border-color: var(--color-border-strong);
}

button.quiet,
button.link {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  color: var(--color-text-subtle);
  min-height: var(--mode-compact-button-min-height, 34px);
  padding: 6px 8px;
}

button.quiet:hover:not(:disabled),
button.link:hover:not(:disabled) {
  background: var(--color-surface-muted);
  border-color: var(--color-border);
  box-shadow: none;
  color: var(--color-text);
}

button.ghost {
  background: transparent;
  border-color: transparent;
}

button.danger {
  background: var(--color-danger);
  border-color: var(--color-danger);
  color: #fff;
}

button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.action-bar {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.action-bar button {
  min-width: 0;
}

.row {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  margin-top: var(--space-2);
}

.row.tight {
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
}

.cluster {
  display: flex;
  gap: var(--space-2);
  flex-wrap: wrap;
}

.tabs {
  display: flex;
  gap: var(--space-1);
  border-bottom: none;
  background: rgba(255, 255, 255, 0.68);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-4);
  overflow-x: auto;
  padding: 4px;
}

.tabs button {
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--color-text-subtle);
  padding: 8px 13px;
  font-weight: 850;
  min-height: 36px;
  white-space: nowrap;
}

.tabs button.active {
  background: #ffffff;
  color: var(--color-primary-strong);
  box-shadow: var(--shadow-xs);
  font-weight: 950;
}

.role-tabs {
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 4px;
  gap: 4px;
}

.role-tabs button {
  flex: 1;
  border-bottom: none;
  border-radius: var(--radius-sm);
}

.role-tabs button.active {
  background: var(--color-primary-soft);
  border-bottom-color: transparent;
}

.flow-card h3 {
  margin: 0 0 6px;
}

.flow-card .subtle {
  margin-top: 0;
}

.hub-flow-header {
  align-items: flex-start;
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
}

.hub-action-count {
  align-items: center;
  background: var(--color-primary-soft);
  border: 1px solid var(--color-green-200);
  border-radius: 999px;
  color: var(--color-primary-strong);
  display: inline-flex;
  font-size: 11px;
  font-weight: 900;
  justify-content: center;
  min-width: 24px;
  padding: 2px 7px;
}

.competition-intent-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-2);
  margin-bottom: var(--space-3);
  overflow-x: auto;
  scrollbar-width: none;
}

.competition-intent-strip::-webkit-scrollbar {
  display: none;
}

.competition-intent-pill {
  align-items: center;
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
  min-height: 58px;
  padding: var(--space-2) var(--space-3);
  text-align: left;
}

.competition-intent-pill:hover {
  background: #ffffff;
  border-color: var(--color-green-200);
}

.competition-intent-pill.active {
  background: var(--color-navy-900);
  border-color: var(--color-navy-900);
  color: #ffffff;
  box-shadow: 0 12px 28px rgba(8, 18, 37, 0.16);
}

.competition-intent-pill.active small {
  color: rgba(255, 255, 255, 0.76);
}

.competition-intent-pill.active .hub-action-count {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.24);
  color: #ffffff;
}

.competition-intent-pill strong,
.competition-intent-pill small {
  display: block;
}

.competition-intent-pill strong {
  font-size: var(--font-size-sm);
  font-weight: 950;
}

.competition-intent-pill small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 750;
  margin-top: 2px;
}

.competition-discovery-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-2);
}

.competition-operation-toolbar {
  align-items: center;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-3);
}

.competition-operation-toolbar button {
  align-items: center;
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  display: inline-flex;
  font-size: var(--font-size-xs);
  font-weight: 900;
  gap: var(--space-1);
  padding: 7px 10px;
}

.competition-operation-list {
  display: grid;
  gap: var(--space-2);
}

.competition-work-summary {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: var(--space-3) 0;
}

.competition-work-summary article {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: var(--space-3);
}

.competition-work-summary span {
  color: var(--color-primary-strong);
  font-size: 1.65rem;
  font-weight: 950;
  line-height: 1;
}

.competition-work-summary strong {
  font-size: var(--font-size-sm);
  font-weight: 950;
}

.competition-work-summary small {
