.home-compact-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.home-compact-card:hover {
  border-color: var(--color-green-200);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.home-action-card,
.home-feed-card,
.home-agenda-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.home-action-card:hover,
.home-feed-card:hover,
.home-agenda-card:hover {
  border-color: var(--color-green-200);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.home-action-card.urgent,
.home-feed-card.urgent {
  border-color: #fed7aa;
  background: #fff7ed;
}

.home-action-card span,
.home-feed-card span {
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  color: var(--color-text-muted);
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 800;
  padding: 3px 9px;
  text-align: center;
}

.home-action-card.urgent span,
.home-feed-card.urgent span {
  background: #ffedd5;
  border-color: #fdba74;
  color: #9a3412;
}

.home-feed-card {
  border-left: 3px solid var(--color-border-strong);
}

.home-feed-card.urgent {
  border-left-color: #fb923c;
}

.home-agenda-card {
  border-left: 4px solid var(--color-primary);
}

.home-agenda-actions {
  align-items: flex-end;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  gap: var(--space-2);
}

.home-agenda-actions span {
  background: var(--color-primary-soft);
  border: 1px solid var(--color-green-200);
  border-radius: 999px;
  color: var(--color-primary-strong);
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 800;
  padding: 3px 9px;
  text-align: center;
}

.home-agenda-actions button {
  min-height: 34px;
  white-space: nowrap;
}

.home-agenda-actions button.primary {
  min-width: 96px;
}

.home-action-label,
.home-action-meta {
  margin: 0;
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
}

.home-action-title {
  margin: 3px 0;
  color: var(--color-text);
  font-weight: 800;
}

.home-action-body {
  color: var(--color-text-muted);
  display: -webkit-box;
  font-size: var(--font-size-sm);
  line-clamp: 2;
  margin: 3px 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
}

.home-compact-title {
  margin: 0;
  color: var(--color-text);
  font-weight: 800;
}

.home-compact-meta {
  margin: 3px 0 0;
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
}

.home-league-chip {
  align-items: center;
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  color: var(--color-text-subtle);
  display: inline-flex;
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 700;
  padding: 2px 8px;
}

.home-league-chip.owner {
  background: #ecfdf5;
  border-color: #a7f3d0;
  color: #047857;
}

.home-league-chip.member {
  background: #eff6ff;
  border-color: #bfdbfe;
  color: #1d4ed8;
}

.home-empty-panel {
  border: 1px dashed var(--color-border-strong);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  color: var(--color-text-subtle);
  display: grid;
  gap: 4px;
  margin-bottom: var(--space-5);
  padding: var(--space-4);
}

.home-empty-panel strong {
  color: var(--color-text);
}

.home-ok-panel {
  background: linear-gradient(180deg, #ffffff 0%, var(--color-primary-soft) 100%);
  border-color: var(--color-green-200);
}

.home-empty-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-2);
}

.home-empty-actions button {
  font-size: var(--font-size-xs);
  min-height: 34px;
}

/* ----- Status badge ----- */
.status-badge {
  display: inline-block;
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  font-size: var(--font-size-xs);
  font-weight: 700;
  border: 1px solid transparent;
}

.status-badge.open {
  background: var(--color-status-open-bg);
  color: var(--color-status-open-fg);
  border-color: var(--color-green-200);
}

.status-badge.live {
  background: var(--color-status-live-bg);
  color: var(--color-status-live-fg);
  border-color: #93c5fd;
}

.status-badge.closed {
  background: var(--color-status-closed-bg);
  color: var(--color-status-closed-fg);
  border-color: var(--color-border-strong);
}

.status-badge.finished {
  background: var(--color-status-finished-bg);
  color: var(--color-status-finished-fg);
  border-color: var(--color-border-strong);
}

.status-badge.draft {
  background: #fef3c7;
  color: #92400e;
  border-color: #fde68a;
}

/* ----- Quick action grid (Home) ----- */
.quick-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-2);
  margin-bottom: var(--space-5);
}

.quick-action {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-3) var(--space-2);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  text-align: center;
  font-size: var(--font-size-xs);
  font-weight: 700;
  color: var(--color-text);
  min-height: 80px;
  transition: border-color 0.12s, background 0.12s;
}

.quick-action:hover {
  border-color: var(--color-primary);
  background: var(--color-primary-soft);
}

.quick-action .qa-icon {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary-strong);
}

.quick-action .qa-icon svg {
  width: 24px;
  height: 24px;
}

.quick-action.disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.quick-action.disabled:hover {
  border-color: var(--color-border);
  background: var(--color-surface);
}

@media (max-width: 480px) {
  .quick-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .page-header {
    align-items: flex-start;
    gap: var(--space-3);
    margin-bottom: var(--space-4);
  }

  .page-header .ph-actions {
    justify-content: flex-start;
    flex-shrink: 0;
  }

  .compact-action {
    padding: 8px 10px;
  }

  .compact-action span:last-child {
    display: none;
  }

  .home-hero {
    align-items: stretch;
    flex-direction: column;
    padding: var(--space-4);
  }

  .home-player-os {
    grid-template-columns: 1fr;
  }

  .home-today-panel {
    gap: var(--space-3);
    padding: var(--space-3);
  }

  .home-today-rows button {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .home-today-rows span {
    grid-column: 1;
    grid-row: auto;
  }

  .home-today-rows strong,
  .home-today-rows small {
    grid-column: 1 / -1;
  }

  .home-today-rows em {
    grid-column: 2;
    grid-row: 1;
  }

  .home-hero::after {
    width: 64%;
  }

  .home-hero-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .home-quick-strip {
    grid-template-columns: 1fr;
  }

  .home-summary-grid {
    grid-template-columns: 1fr;
  }

  .home-player-side .home-summary-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .player-hub-grid {
    grid-template-columns: 1fr;
  }

  .player-hub-workspace {
    grid-template-columns: 1fr;
  }

  .player-hub-brief {
    grid-template-columns: 1fr;
  }

  .home-section .event-card {
    grid-template-columns: 84px minmax(0, 1fr);
  }

  .home-section .event-card .ec-poster,
  .home-section .event-card .ec-poster-placeholder {
    min-height: 96px;
  }

  .home-discovery-carousel {
    grid-auto-columns: minmax(238px, 84vw);
    margin-left: calc(var(--space-3) * -1);
    margin-right: calc(var(--space-3) * -1);
    padding-left: var(--space-3);
    padding-right: var(--space-3);
  }

  .home-discovery-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 2px;
  }

  .home-empty-inline {
    align-items: stretch;
    flex-direction: column;
  }

  .home-action-card,
  .home-compact-card {
    align-items: flex-start;
    flex-direction: column;
  }

  .tournament-registration-hero,
  .tournament-registration-grid {
    grid-template-columns: 1fr;
  }

  .tournament-registration-hero {
    padding: var(--space-3);
  }

  .tournament-registration-hero img {
    max-height: 220px;
  }
}

/* ----- Event card (ATP APP style) ----- */
.events-kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}

.events-kpi-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-3);
}

.events-kpi-label {
  margin: 0;
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
}

.events-kpi-value {
  margin: 2px 0 0;
  font-size: var(--font-size-xl);
  font-weight: 800;
  color: var(--color-text);
}

.events-kpi-grid.organizing-summary {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.events-kpi-grid.organizing-summary .events-kpi-card {
  align-items: baseline;
  display: inline-flex;
  gap: 6px;
  min-height: 0;
  padding: 7px 12px;
}

.events-kpi-grid.organizing-summary .events-kpi-label,
.events-kpi-grid.organizing-summary .events-kpi-value {
  margin: 0;
}

.events-kpi-grid.organizing-summary .events-kpi-label {
  order: 2;
}

.events-kpi-grid.organizing-summary .events-kpi-value {
  font-size: var(--font-size-md);
  order: 1;
}

.events-filter-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-3);
  margin-bottom: var(--space-3);
}

.events-filter-disclosure {
  display: grid;
  gap: var(--space-3);
}

.events-filter-disclosure summary {
  align-items: center;
  cursor: pointer;
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
  list-style: none;
}

.events-filter-disclosure summary::-webkit-details-marker {
  display: none;
}

.events-filter-disclosure summary span {
  color: var(--color-text);
  font-weight: 950;
}

.events-filter-disclosure summary small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 850;
  text-align: right;
}

.events-filter-actions {
  display: flex;
  justify-content: flex-end;
}

.events-filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-2);
}

.events-filter-grid label {
  display: block;
  margin-bottom: 6px;
}

.organizer-tournament-command {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
}

.organizer-tournament-command-head {
  align-items: start;
  display: grid;
  gap: var(--space-3);
  grid-template-columns: minmax(0, 1fr) auto;
}

.organizer-tournament-command-head span,
.events-result-head span,
.organizer-tournament-main > span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.organizer-tournament-command-head h2 {
  color: var(--color-text);
  font-size: var(--font-size-xl);
  line-height: var(--line-tight);
  margin: 0;
}

.organizer-tournament-command-head p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 800;
  margin: 4px 0 0;
}

.organizer-tournament-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}

.organizer-tournament-chip-row span {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text-muted);
  display: inline-flex;
  font-size: var(--font-size-xs);
  font-weight: 850;
  gap: 6px;
  padding: 5px 10px;
}

.organizer-tournament-chip-row strong {
  color: var(--color-text);
}

.organizer-tournament-list,
.events-result-list.organizing {
  display: grid;
  gap: var(--space-2);
}

.organizer-tournament-row {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-xs);
  cursor: pointer;
  display: grid;
  gap: var(--space-3);
  grid-template-columns: minmax(0, 1fr) minmax(120px, 0.38fr) auto;
  padding: var(--space-3);
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.organizer-tournament-row:hover {
  border-color: var(--color-green-200);
  box-shadow: var(--shadow-sm);
  transform: translateY(-1px);
}

.organizer-tournament-main,
.organizer-tournament-meta {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.organizer-tournament-main strong {
  color: var(--color-text);
  font-size: var(--font-size-md);
  line-height: var(--line-tight);
  overflow-wrap: anywhere;
}

.organizer-tournament-main small,
.organizer-tournament-meta small,
.events-result-head small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.organizer-tournament-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  justify-content: flex-end;
}

.organizer-tournament-actions button {
  min-height: 36px;
}

.events-result-list {
  margin-top: var(--space-1);
}

.events-result-head {
  align-items: end;
  display: flex;
  justify-content: space-between;
}

.events-all-disclosure {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xs);
  margin-top: var(--space-3);
  padding: var(--space-3);
}

.events-all-disclosure summary {
  align-items: center;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  list-style: none;
}

.events-all-disclosure summary::-webkit-details-marker {
  display: none;
}

.events-all-disclosure summary span {
  color: var(--color-text);
  font-weight: 950;
}

.events-all-disclosure summary small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 850;
}

.events-all-disclosure[open] summary {
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--space-2);
  padding-bottom: var(--space-2);
}

.event-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-bottom: var(--space-3);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.event-card:hover {
  border-color: var(--color-green-200);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.event-card .ec-poster {
  width: 100%;
  aspect-ratio: 16 / 7;
  object-fit: cover;
  display: block;
  background: var(--color-primary-soft);
}

.event-card .ec-poster-placeholder {
  width: 100%;
  aspect-ratio: 16 / 7;
  background: var(--color-navy-900);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 34px;
  font-weight: 900;
}

.event-card .ec-body {
  padding: var(--space-3) var(--space-4);
}

.event-card .ec-name-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}

.event-card .ec-name {
  font-size: var(--font-size-md);
  font-weight: 800;
  color: var(--color-text);
  margin: 0;
  flex: 1;
  min-width: 0;
}

.event-card .ec-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: var(--space-2);
}

.event-card .ec-chip {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  border: 1px solid var(--color-border);
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 700;
  color: var(--color-text-subtle);
  background: #f8fafc;
}

.event-card .ec-chip.owner {
  border-color: #a7f3d0;
  color: #047857;
  background: #ecfdf5;
}

.event-card .ec-chip.member {
  border-color: #bfdbfe;
  color: #1d4ed8;
  background: #eff6ff;
}

.event-card .ec-divider {
  height: 1px;
  background: var(--color-border);
  margin: 0 0 var(--space-2);
}

.event-card .ec-info-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) 0;
  border-bottom: 1px solid var(--color-border);
  gap: var(--space-2);
}

.event-card .ec-info-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.event-card .ec-info-left {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--color-text-muted);
  font-size: var(--font-size-sm);
}

.event-card .ec-info-left svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  color: var(--color-text-subtle);
}

.event-card .ec-chevron {
  color: var(--color-text-subtle);
  flex-shrink: 0;
}

.event-card .ec-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-2);
  margin-top: var(--space-1);
  font-size: var(--font-size-sm);
  color: var(--color-text-subtle);
  border-top: 1px solid var(--color-border);
}

.event-card .ec-footer-left {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

@media (max-width: 720px) {
  .competition-intent-strip {
    grid-template-columns: repeat(3, minmax(158px, 1fr));
    margin-left: calc(var(--mode-page-padding-mobile, var(--space-4)) * -0.25);
    margin-right: calc(var(--mode-page-padding-mobile, var(--space-4)) * -0.25);
    padding: 0 calc(var(--mode-page-padding-mobile, var(--space-4)) * 0.25) var(--space-1);
  }

  .competition-operation-row {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .competition-operation-row button {
    width: 100%;
  }

  .competition-list-note {
    align-items: stretch;
    display: grid;
    grid-template-columns: 1fr;
  }

  .competition-focus-panel {
    grid-template-columns: 1fr;
  }

  .competition-focus-metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    overflow-x: auto;
  }

  .competition-discovery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .competition-discovery-carousel {
    grid-auto-columns: minmax(230px, 82vw);
  }

  .competition-discovery-head {
    align-items: flex-start;
  }

  .competition-starter-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .events-kpi-grid:not(.organizing-summary) {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .events-filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .organizer-tournament-command-head,
  .organizer-tournament-row {
    grid-template-columns: 1fr;
  }

  .organizer-tournament-actions {
