  border: none;
  cursor: pointer;
  font-size: var(--font-size-md);
}

@media (max-width: 720px) {
  .personal-area-grid,
  .personal-area-detail dl {
    grid-template-columns: 1fr;
  }

  .personal-area-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .league-core-state-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .league-match-main,
  .league-match-next-state {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  .league-match-context {
    display: grid;
    justify-content: stretch;
  }

  .league-match-context > *,
  .league-match-actions button {
    width: 100%;
  }

  .league-match-actions {
    display: grid;
    justify-content: stretch;
  }

  .league-standings-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .league-standings-table {
    overflow-x: visible;
  }

  .league-standings-row {
    gap: 6px;
    grid-template-columns: 32px minmax(0, 1fr) 42px 42px 46px 42px;
    min-width: 0;
    padding: 10px var(--space-2);
  }

  .league-standings-row.head {
    font-size: 10px;
  }

  .league-standings-row span {
    font-size: var(--font-size-xs);
  }

  .league-standings-row strong {
