.place-public-court-calendar-card header {
  border-bottom: 1px solid var(--color-border);
  display: block;
  padding-bottom: var(--space-2);
}

.place-public-court-calendar-card header strong {
  color: var(--color-text);
  display: block;
  font-size: var(--font-size-md);
  line-height: var(--line-tight);
}

.place-public-court-calendar-card header small {
  color: var(--color-text-subtle);
  display: block;
  font-size: var(--font-size-xs);
  font-weight: 800;
  line-height: var(--line-body);
  margin-top: 2px;
}

.place-public-hour-list {
  display: grid;
  gap: 7px;
}

.place-public-hour-list button {
  align-items: center;
  background: var(--color-primary-soft);
  border: 1px solid rgba(16, 185, 129, 0.22);
  border-radius: var(--radius-sm);
  color: var(--color-primary-strong);
  display: flex;
  justify-content: space-between;
  min-height: 38px;
  padding: 7px 9px;
  text-align: left;
}

.place-public-hour-list button.busy,
.place-public-hour-list button.past,
.place-public-hour-list button:disabled {
  background: var(--color-surface-muted);
  border-color: var(--color-border);
  color: var(--color-text-subtle);
  cursor: not-allowed;
  opacity: 0.78;
}

.place-public-hour-list button.selected {
  background: var(--color-primary-strong);
  border-color: var(--color-primary-strong);
  box-shadow: var(--shadow-sm);
  color: #fff;
}

.place-public-hour-list button.selected-range {
  background: rgba(16, 185, 129, 0.13);
  border-color: rgba(16, 185, 129, 0.42);
  color: var(--color-primary-strong);
  cursor: default;
  opacity: 1;
}

.place-public-hour-list button span {
  font-size: var(--font-size-sm);
  font-weight: 950;
}

.place-public-hour-list button small {
  font-size: var(--font-size-xs);
  font-weight: 900;
}

.place-public-manual-slot {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(0, 1fr) minmax(92px, 0.55fr);
}

.personal-area-page {
  display: grid;
  gap: var(--space-4);
}

.personal-area-header {
  background: linear-gradient(135deg, #f8fffb 0%, #ffffff 70%);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-4);
}

.personal-area-header span,
.personal-area-card header span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.personal-area-header h1 {
  margin: 4px 0;
}

.personal-area-header p {
  color: var(--color-text-subtle);
  margin: 0;
}

.personal-area-grid {
  display: grid;
  gap: var(--space-3);
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.personal-area-card {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-2);
  padding: var(--space-3);
}

.personal-area-card header {
  align-items: center;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  padding-bottom: var(--space-2);
}

.personal-area-card h2 {
  font-size: var(--font-size-lg);
  margin: 0;
}

.personal-area-card header b {
  align-items: center;
  border: 1px solid var(--color-green-200);
  border-radius: 999px;
  color: var(--color-primary-strong);
  display: inline-flex;
  min-height: 32px;
  min-width: 32px;
  justify-content: center;
  padding: 0 10px;
}

.personal-area-row {
  align-items: center;
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
  min-height: 64px;
  padding: 10px 12px;
  text-align: left;
  text-decoration: none;
  width: 100%;
}

.personal-area-row.static {
  pointer-events: none;
}

.personal-area-row strong,
.personal-area-row small {
  display: block;
}

.personal-area-row small {
  color: var(--color-text-subtle);
  font-weight: 800;
  margin-top: 2px;
}

.status-pill {
  border: 1px solid var(--color-border);
  border-radius: 999px;
  font-size: var(--font-size-xs);
  font-style: normal;
  font-weight: 900;
  padding: 5px 8px;
  white-space: nowrap;
}

.status-pill.tone-ok {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  color: var(--color-primary-strong);
}

.status-pill.tone-pending {
  background: #fff7ed;
  border-color: #fed7aa;
  color: #9a3412;
}

.status-pill.tone-danger {
  background: #fef2f2;
  border-color: #fecaca;
  color: #991b1b;
}

.status-pill.tone-muted {
  background: var(--color-surface-muted);
  color: var(--color-text-subtle);
}

.personal-area-detail {
  display: grid;
  gap: var(--space-3);
}

.personal-area-detail dl {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 0;
}

.personal-area-detail dt {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.personal-area-detail dd {
  font-weight: 800;
  margin: 2px 0 0;
}

.personal-agenda-page {
  gap: var(--space-3);
}

.personal-agenda-hero {
  align-items: end;
  display: grid;
  gap: var(--space-3);
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.7fr);
}

.personal-agenda-kpis,
.personal-agenda-state-grid {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.personal-agenda-kpis article,
.personal-agenda-summary-card {
  background: rgba(255, 255, 255, 0.88);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: 4px;
  padding: var(--space-2);
  text-decoration: none;
}

.personal-agenda-kpis article span,
.personal-agenda-summary-card span,
.personal-agenda-kind {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.personal-agenda-kpis article strong,
.personal-agenda-summary-card strong {
  color: var(--color-text);
  font-size: var(--font-size-2xl);
  line-height: 1;
}

.personal-agenda-kpis article small,
.personal-agenda-summary-card small {
  color: var(--color-text-subtle);
  font-weight: 850;
  line-height: 1.25;
}

.personal-agenda-kpis article.danger strong,
.personal-agenda-kpis article.danger span {
  color: #b91c1c;
}

.personal-agenda-tabs {
  display: flex;
  gap: var(--space-2);
  overflow-x: auto;
  padding-bottom: 2px;
}

.personal-agenda-tabs button {
  border-radius: 999px;
  flex: 0 0 auto;
  min-height: 40px;
}

.personal-agenda-tabs button.active {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: #fff;
}

.personal-agenda-layout {
  align-items: start;
  display: grid;
  gap: var(--space-3);
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.42fr);
}

.personal-agenda-main,
.personal-agenda-list {
  display: grid;
  gap: var(--space-2);
}

.personal-agenda-state-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.personal-agenda-item {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  display: grid;
  gap: 6px;
  grid-template-columns: minmax(0, 1fr) auto;
  padding: var(--space-3);
  text-align: left;
  transition: border-color 160ms ease, transform 160ms ease;
  width: 100%;
}

.personal-agenda-item:hover,
.personal-agenda-item.active {
  border-color: rgba(32, 185, 109, 0.45);
  transform: translateY(-1px);
}

.personal-agenda-item strong,
.personal-agenda-item small,
.personal-agenda-item em {
  display: block;
}

.personal-agenda-item strong {
  font-size: var(--font-size-lg);
  line-height: var(--line-title);
}

.personal-agenda-item small,
.personal-agenda-item em {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-style: normal;
  font-weight: 850;
}

.personal-agenda-item .status-pill {
  align-self: start;
  grid-column: 2;
  grid-row: 1 / span 4;
}

.personal-agenda-detail-panel {
  position: sticky;
  top: 20px;
}

.personal-agenda-detail,
.personal-agenda-empty-detail {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-3);
  padding: var(--space-3);
}

.personal-agenda-detail-head {
  display: grid;
  gap: 6px;
}

.personal-agenda-detail-head strong,
.personal-agenda-empty-detail strong {
  font-size: var(--font-size-xl);
  line-height: var(--line-title);
}

.personal-agenda-detail-head small,
.personal-agenda-empty-detail small {
  color: var(--color-text-subtle);
  font-weight: 850;
}

.personal-agenda-detail dl {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 0;
}

.personal-agenda-detail dt {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.personal-agenda-detail dd {
  font-weight: 850;
  margin: 2px 0 0;
  min-width: 0;
  overflow-wrap: anywhere;
}

.place-public-manual-slot button {
  grid-column: 1 / -1;
}

.place-public-manual-slot label,
.place-public-booking-form label {
  min-width: 0;
}

.place-public-booking-empty,
.place-public-selected-slot,
.place-public-booking-feedback,
.place-public-profile-link {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  display: grid;
  gap: 5px;
  padding: var(--space-2);
}

.place-public-booking-empty.compact {
  border-style: dashed;
}

.place-public-booking-empty strong,
.place-public-selected-slot strong,
.place-public-profile-link strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
}

.place-public-booking-empty span,
.place-public-selected-slot span,
.place-public-booking-feedback,
.place-public-profile-link span,
.place-public-profile-link small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
  line-height: var(--line-body);
}

.place-public-booking-form .wide {
  grid-column: 1 / -1;
}

.place-public-booking-flow-card .place-public-hero-actions {
  margin-top: 0;
}

@media (max-width: 980px) {
  .place-public-booking-steps {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .place-public-booking-header {
    align-items: stretch;
    display: grid;
  }

  .place-public-booking-mini {
    justify-content: center;
    width: max-content;
  }

  .place-public-booking-flow-card .place-public-availability-controls {
    grid-template-columns: minmax(0, 1fr) minmax(92px, 0.72fr);
  }

  .place-public-booking-flow-card .place-public-availability-controls button,
  .place-public-manual-slot button {
    grid-column: 1 / -1;
  }

  .place-public-booking-flow-card .place-public-availability-board > div {
    grid-template-columns: 48px minmax(0, 1fr);
  }

  .place-public-court-carousel {
    grid-auto-columns: minmax(250px, 86vw);
  }

  .place-public-booking-flow-card .place-public-hero-actions button {
    flex: 1 1 150px;
  }
}

/* ----- Place card ----- */
.place-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  display: grid;
  grid-template-columns: 1fr 64px;
  gap: var(--space-3);
  align-items: start;
  margin-bottom: var(--space-2);
  box-shadow: var(--shadow-sm);
}

.place-card .pc-name {
  font-weight: 800;
  margin: 0 0 6px;
  color: var(--color-text);
  font-size: var(--font-size-md);
}

.place-card .pc-meta {
  font-size: var(--font-size-sm);
  color: var(--color-text-subtle);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.place-card .pc-meta-row {
  display: flex;
  align-items: center;
  gap: 5px;
}

.place-card .pc-meta-row svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: var(--color-text-subtle);
}

.place-feature-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: var(--space-2);
}

.place-feature-strip span {
  background: #eef6f1;
  border: 1px solid #cfe9d8;
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  font-size: 11px;
  font-weight: 900;
  padding: 3px 8px;
}

.place-public-description {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 700;
  line-height: 1.45;
  margin: var(--space-2) 0 0;
}

.place-public-highlights {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: var(--space-3);
}

.place-public-highlights span {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-subtle);
  display: grid;
  font-size: var(--font-size-xs);
  font-weight: 900;
  min-height: 56px;
  padding: var(--space-2);
}

.place-public-highlights strong {
  color: var(--color-text);
  font-size: var(--font-size-lg);
  line-height: 1;
}

.court-discovery-results {
  display: grid;
  gap: var(--space-3);
  margin-bottom: var(--space-4);
}

.court-discovery-results-head {
  align-items: end;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  padding-bottom: var(--space-3);
}

.court-discovery-results-head span,
.court-discovery-kicker {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.court-discovery-results-head h2 {
  color: var(--color-text);
  font-size: var(--font-size-xl);
  line-height: var(--line-title);
  margin: 2px 0 0;
}

.court-discovery-results-head p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 750;
  margin: 4px 0 0;
}

.court-discovery-results-head strong {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  font-size: var(--font-size-sm);
  padding: 7px 11px;
  white-space: nowrap;
}

.court-discovery-grid {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.court-discovery-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  color: inherit;
  display: grid;
  gap: 6px;
  min-height: 154px;
  padding: var(--space-4);
  text-align: left;
  transition:
    border-color 140ms ease,
    box-shadow 140ms ease,
    transform 140ms ease;
}

.court-discovery-card:hover {
  border-color: var(--color-green-200);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.court-discovery-card strong {
  color: var(--color-navy-900);
  font-size: var(--font-size-lg);
  font-weight: 950;
  line-height: var(--line-title);
}

.court-discovery-card small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 850;
}

.court-discovery-card div {
  align-items: center;
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
  margin-top: var(--space-2);
}

.court-discovery-card div span {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
  padding: 4px 8px;
}

.court-discovery-card b {
  color: var(--color-primary-strong);
  font-size: var(--font-size-md);
  font-weight: 950;
}

.court-discovery-card em {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-style: normal;
  font-weight: 800;
  margin-top: 2px;
}

.court-discovery-cta {
  align-items: center;
  background: rgba(22, 137, 79, 0.1);
  border: 1px solid var(--color-green-200);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  display: inline-flex;
  font-size: var(--font-size-xs);
  font-weight: 950;
  justify-content: center;
  margin-top: var(--space-2);
  padding: 7px 10px;
  width: fit-content;
}

@media (max-width: 520px) {
  .court-discovery-results-head {
    align-items: start;
    flex-direction: column;
  }

  .court-discovery-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .court-discovery-card {
    min-height: 132px;
  }
}

.place-public-page {
  display: grid;
  gap: var(--space-3);
}

.place-public-topbar {
  align-items: center;
  display: grid;
  gap: var(--space-2);
  grid-template-columns: auto minmax(0, 1fr) auto;
}

.place-public-topbar > div {
  min-width: 0;
  text-align: center;
}

.place-public-topbar span {
  color: var(--color-text-subtle);
  display: block;
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.place-public-topbar strong {
  color: var(--color-text);
  display: block;
  font-size: var(--font-size-sm);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.place-public-hero {
  align-items: center;
  background:
    radial-gradient(circle at 90% 0%, rgba(84, 201, 139, 0.22), transparent 34%),
    linear-gradient(135deg, #052e2b 0%, #0f513f 58%, #164e63 100%);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  color: #fff;
  display: grid;
  gap: var(--space-4);
  grid-template-columns: 132px minmax(0, 1fr);
  padding: var(--space-5);
}

.place-public-hero.has-cover {
  grid-template-columns: 132px minmax(0, 1fr) minmax(220px, 0.72fr);
}

.place-public-hero-logo {
  align-items: center;
  aspect-ratio: 1;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: var(--radius-md);
  color: #fff;
  display: flex;
  font-size: var(--font-size-2xl);
  font-weight: 950;
  justify-content: center;
  overflow: hidden;
}

.place-public-hero-logo img {
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.place-public-cover {
  aspect-ratio: 4 / 3;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: var(--radius-md);
  box-shadow: 0 18px 36px rgba(0, 32, 51, 0.22);
  overflow: hidden;
}

.place-public-cover img {
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.place-public-hero span {
  color: rgba(255, 255, 255, 0.74);
  font-size: var(--font-size-xs);
  font-weight: 850;
}

.place-public-hero h1,
.place-public-hero h2 {
  color: #fff;
  font-size: var(--font-size-3xl);
  line-height: 1;
  margin: var(--space-1) 0 var(--space-2);
}

.place-public-hero p {
  color: rgba(255, 255, 255, 0.8);
  font-weight: 700;
  margin: 0;
  max-width: 720px;
}

.place-public-offer-strip {
  align-items: center;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: var(--radius-md);
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: space-between;
  margin-top: var(--space-3);
  max-width: 760px;
  padding: var(--space-2) var(--space-3);
}

.place-public-offer-strip strong {
  color: #fff;
  font-size: var(--font-size-sm);
}

.place-public-offer-strip small {
  color: rgba(255, 255, 255, 0.68);
  font-size: var(--font-size-xs);
  font-weight: 750;
}

.place-public-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-3);
}

.place-public-action-rail {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(auto-fit, minmax(156px, 1fr));
}

.place-public-action-rail button {
