}

.place-public-overview-list button:hover {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
}

.place-public-overview-list strong,
.place-public-overview-empty strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
}

.place-public-overview-list small,
.place-public-overview-empty small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
  line-height: var(--line-body);
}

.place-public-about-grid {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.place-public-about-grid span {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  display: grid;
  gap: 3px;
  padding: var(--space-2);
}

.place-public-about-grid small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.place-public-about-grid strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
}

.place-public-row {
  border-top: 1px solid var(--color-border);
