.places-intent-panel {
  align-items: stretch;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--mode-card-radius);
  box-shadow: var(--mode-surface-shadow);
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(200px, 0.42fr) minmax(0, 1fr);
  margin-bottom: var(--space-3);
  padding: var(--mode-card-padding);
}

.places-intent-copy {
  align-content: center;
  display: grid;
  gap: 4px;
  min-width: 0;
}

.places-intent-copy span,
.places-section-head span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  letter-spacing: 0;
  text-transform: uppercase;
}

.places-intent-copy h2,
.places-section-head h2 {
  color: var(--color-text);
  font-size: var(--font-size-xl);
  line-height: var(--line-tight);
  margin: 0;
}

.places-intent-copy p,
.places-section-head p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 750;
  line-height: 1.45;
  margin: 0;
}

.places-intent-actions {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.places-intent-strip {
  display: flex;
  gap: var(--space-2);
  margin: 0 0 var(--space-3);
  overflow-x: auto;
  padding: 0 0 2px;
  scroll-snap-type: x proximity;
}

.places-intent-strip::-webkit-scrollbar {
  height: 0;
}

.places-intent-strip button {
  align-items: start;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  display: grid;
  flex: 1 0 180px;
  gap: 3px;
  min-height: 62px;
  padding: var(--space-2);
  scroll-snap-align: start;
  text-align: left;
}

.places-intent-strip button.active {
  background: var(--color-primary-strong);
  border-color: var(--color-primary-strong);
  color: #fff;
  box-shadow: var(--shadow-sm);
}

.places-intent-strip strong {
  font-size: var(--font-size-sm);
  line-height: var(--line-tight);
}

.places-intent-strip span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.places-intent-strip button.active span {
  color: rgba(255, 255, 255, 0.78);
}

.places-intent-card {
  align-items: start;
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  display: grid;
  gap: 4px;
  justify-content: stretch;
  min-height: 86px;
  padding: var(--space-2);
  text-align: left;
  transition: background 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.places-intent-card:hover {
  border-color: rgba(10, 85, 68, 0.32);
  box-shadow: var(--shadow-sm);
  transform: translateY(-1px);
}

.places-intent-card.active {
  background: var(--color-primary-strong);
  border-color: var(--color-primary-strong);
  box-shadow: var(--shadow-sm);
  color: #fff;
}

.places-intent-card strong {
  font-size: var(--font-size-sm);
  line-height: var(--line-tight);
}

.places-intent-card span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
  line-height: 1.35;
}

.places-intent-card small {
  align-self: end;
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
}

.places-intent-card.active span,
.places-intent-card.active small {
  color: rgba(255, 255, 255, 0.78);
}

.places-scope-tabs {
  margin-bottom: var(--space-3);
  max-width: 520px;
}

.places-directory-toolbar {
  align-items: end;
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(180px, 1fr) minmax(140px, 0.42fr) 86px auto;
  margin-bottom: var(--space-3);
  padding: var(--space-2);
}

.places-directory-toolbar label {
  color: var(--color-text-subtle);
  display: grid;
  font-size: var(--font-size-xs);
  font-weight: 900;
  gap: 5px;
  min-width: 0;
}

.places-start-state {
  align-items: center;
  background: rgba(255, 255, 255, 0.74);
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: var(--radius-md);
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  margin-bottom: var(--space-3);
  padding: var(--space-3);
}

.places-start-state > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.places-start-state span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.places-start-state strong {
  color: var(--color-text);
  font-size: var(--font-size-md);
  line-height: var(--line-tight);
}

.places-start-state p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 750;
  line-height: 1.45;
  margin: 0;
}

.places-section-head {
  align-items: end;
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  margin: var(--space-2) 0 var(--space-2);
}

.places-section-head > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.places-section-head > div > strong,
.places-section-head > div > small {
  display: block;
  line-height: var(--line-title);
}

.places-section-head strong {
  color: var(--color-text-subtle);
  flex: 0 0 auto;
  font-size: var(--font-size-xs);
  font-weight: 950;
}

.places-discovery-filter {
  background: var(--color-surface);
  border: 1px solid rgba(10, 85, 68, 0.16);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
}

.places-discovery-filter.compact {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  margin-bottom: var(--space-2);
}

.places-filter-head {
  align-items: end;
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
}

.places-filter-head > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.places-filter-head span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.places-filter-head strong {
  color: var(--color-text);
  font-size: var(--font-size-md);
  line-height: var(--line-tight);
}

.places-filter-head small,
.places-filter-head b {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 850;
}

.places-filter-head b {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  flex: 0 0 auto;
  padding: 6px 10px;
}

.places-filter-grid {
  align-items: end;
  display: grid;
  gap: var(--space-2);
}

.places-filter-mobile-toggle {
  display: none;
}

.places-filter-grid.court {
  grid-template-areas:
    "state state city city city place place place place surface surface surface"
    "date date date time time time duration duration duration submit submit submit";
  grid-template-columns: repeat(12, minmax(0, 1fr));
}

.places-filter-grid.court .court-filter-state {
  grid-area: state;
}

.places-filter-grid.court .court-filter-city {
  grid-area: city;
}

.places-filter-grid.court .court-filter-place {
  grid-area: place;
}

.places-filter-grid.court .court-filter-surface {
  grid-area: surface;
}

.places-filter-grid.court .court-filter-date {
  grid-area: date;
}

.places-filter-grid.court .court-filter-time {
  grid-area: time;
}

.places-filter-grid.court .court-filter-duration {
  grid-area: duration;
}

.places-filter-grid.classes {
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-template-areas:
    "state state city city city query query query query period period period"
    "days days days days days days level level level profile profile submit";
}

.places-filter-grid.classes .class-filter-state {
  grid-area: state;
}

.places-filter-grid.classes .class-filter-city {
  grid-area: city;
}

.places-filter-grid.classes .class-filter-query {
  grid-area: query;
}

.places-filter-grid.classes .class-filter-period {
  grid-area: period;
}

.places-filter-grid.classes .class-filter-weekdays {
  align-items: center;
  border: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  grid-area: days;
  margin: 0;
  min-width: 0;
  padding: 0;
}

.places-filter-grid.classes .class-filter-weekdays legend {
  color: var(--color-text-subtle);
  flex-basis: 100%;
  font-size: var(--font-size-xs);
  font-weight: 900;
  line-height: var(--line-tight);
  padding: 0;
}

.places-filter-grid.classes .class-filter-weekdays button {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  font-size: var(--font-size-xs);
  font-weight: 900;
  min-height: 34px;
  padding: 6px 10px;
  width: auto;
}

.places-filter-grid.classes .class-filter-weekdays button.selected {
  background: var(--color-primary-soft);
  border-color: var(--color-primary-border);
  color: var(--color-primary-strong);
}

.places-filter-grid.classes .class-filter-level,
.places-filter-grid.classes .class-filter-profile {
  min-width: 0;
}

.places-filter-grid.classes .class-filter-level {
  grid-area: level;
}

.places-filter-grid.classes .class-filter-profile {
  grid-area: profile;
}

.places-filter-grid.matches {
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-template-areas:
    "state state city city city place place place date date period period"
    "level level level status status query query query query clear clear clear";
}

.places-filter-grid.matches .match-filter-state {
  grid-area: state;
}

.places-filter-grid.matches .match-filter-city {
  grid-area: city;
}

.places-filter-grid.matches .match-filter-place {
  grid-area: place;
}

.places-filter-grid.matches .match-filter-date {
  grid-area: date;
}

.places-filter-grid.matches .match-filter-period {
  grid-area: period;
}

.places-filter-grid.matches .match-filter-level {
  grid-area: level;
}

.places-filter-grid.matches .match-filter-status {
  grid-area: status;
}

.places-filter-grid.matches .match-filter-query {
  grid-area: query;
}

.places-filter-grid.matches .match-filter-clear {
  grid-area: clear;
}

.places-filter-grid label {
  color: var(--color-text-subtle);
  display: grid;
  font-size: var(--font-size-xs);
  font-weight: 900;
  gap: 5px;
  min-width: 0;
}

.places-filter-grid input,
.places-filter-grid select {
  box-sizing: border-box;
  min-width: 0;
  width: 100%;
}

.places-filter-grid button {
  min-height: 44px;
  white-space: nowrap;
}

.places-filter-grid.court button {
  align-items: center;
  display: inline-flex;
  grid-area: submit;
  justify-content: center;
  justify-self: stretch;
  min-width: 52px;
  padding-inline: 0;
  width: 52px;
}

.places-filter-grid.court .places-filter-search-button {
  border-radius: var(--radius-md);
  justify-self: end;
  width: min(100%, 64px);
}

.places-filter-search-button svg {
  height: 20px;
  width: 20px;
}

.places-filter-grid.classes button {
  width: 100%;
}

.places-filter-grid.classes .class-filter-weekdays button {
  width: auto;
}

.places-filter-grid.classes .class-filter-submit {
  grid-area: submit;
}

.open-matches-panel {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
}

.open-match-form {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(140px, 1fr) minmax(160px, 1fr) minmax(90px, 0.7fr) minmax(140px, 1fr) auto;
}

.open-match-community-grid {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.open-match-community-grid div {
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-2);
}

.open-match-community-grid strong {
  color: var(--color-text);
  display: block;
  font-size: var(--font-size-xl);
  line-height: 1;
}

.open-match-community-grid span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
}

.open-match-filter {
  align-items: center;
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(0, 1fr) minmax(150px, 0.35fr) auto;
}

.open-match-create-intro {
  align-items: center;
  border-top: 1px solid var(--color-border);
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
  padding-top: var(--space-2);
}

.open-match-create-intro > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.open-match-create-intro strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
}

.open-match-create-intro small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
  text-align: right;
}

.open-match-filter-panel {
  border-top: 1px solid var(--color-border);
  display: grid;
  gap: var(--space-2);
  padding-top: var(--space-2);
}

.open-match-filter-panel summary {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  font-size: var(--font-size-xs);
  font-weight: 950;
  gap: var(--space-1);
  justify-content: center;
  list-style: none;
  min-height: 38px;
  padding: 0 var(--space-2);
  width: fit-content;
}

.open-match-filter-panel summary::-webkit-details-marker {
  display: none;
}

.open-match-filter-panel summary span {
  align-items: center;
  background: rgba(10, 85, 68, 0.12);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  display: inline-flex;
  font-size: var(--font-size-xs);
  justify-content: center;
  min-width: 22px;
  padding: 2px 6px;
}

.open-match-filter-panel > div {
  padding-top: var(--space-1);
}

.open-match-filter-panel > button {
  justify-self: start;
}

.open-match-filter span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
}

.open-match-list {
  display: grid;
  gap: var(--space-2);
}

.open-match-row {
  align-items: stretch;
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-2);
}

.open-match-main {
  align-items: center;
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
}

.open-match-main > div:first-child {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.open-match-row span,
.open-match-row small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
}

.open-match-status {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  display: inline-flex;
  font-weight: 900;
  padding: 2px 8px;
  width: fit-content;
}

.open-match-status.open {
  background: #ecfdf5;
  border-color: #a7f3d0;
  color: #047857;
}

.open-match-status.closed {
  background: #eff6ff;
  border-color: #bfdbfe;
  color: #1d4ed8;
}

.open-match-status.cancelled {
  background: #f8fafc;
  color: var(--color-text-subtle);
}

.open-match-actions {
  display: flex;
  flex-wrap: wrap;
  flex-shrink: 0;
  gap: var(--space-2);
}

.open-match-actions .open-match-more summary {
  min-width: 84px;
}

.open-match-comments {
  border-top: 1px solid var(--color-border);
  display: grid;
  gap: var(--space-2);
  padding-top: var(--space-2);
}

.open-match-comments small {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 5px 7px;
}

.open-match-comments div {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(0, 1fr) auto;
}

.place-enrollment-chip {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  display: flex;
  gap: var(--space-2);
  padding: 4px 6px;
}

@media (max-width: 760px) {
  .places-intent-panel {
    grid-template-columns: 1fr;
    padding: var(--space-2);
  }

  .places-intent-actions {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .places-intent-card {
    min-height: 78px;
  }

  .places-intent-strip {
    margin-inline: calc(-1 * var(--space-2));
    padding-inline: var(--space-2);
  }

  .places-intent-strip button {
    flex-basis: 154px;
    min-height: 58px;
  }

  .places-directory-toolbar {
    grid-template-columns: 1fr 86px;
  }

  .places-directory-search {
    grid-column: 1 / -1;
  }

  .places-directory-toolbar button {
    grid-column: 1 / -1;
  }

  .places-start-state {
    align-items: stretch;
    display: grid;
  }

  .places-section-head,
  .open-match-create-intro,
  .places-filter-head {
    align-items: start;
    flex-direction: column;
  }

  .open-match-create-intro small {
    text-align: left;
  }

  .place-court-create,
  .place-booking-form,
  .place-academy-form,
  .open-match-form,
  .place-staff-form {
    grid-template-columns: 1fr;
  }

  .open-match-community-grid {
    grid-template-columns: 1fr;
  }

  .open-match-filter {
    grid-template-columns: 1fr;
  }

  .places-filter-grid.court,
  .places-filter-grid.classes,
  .places-filter-grid.matches {
    grid-auto-flow: row;
    grid-template-areas: unset;
    grid-template-columns: 1fr;
    width: 100%;
  }

  .places-filter-grid.court > *,
  .places-filter-grid.classes > *,
  .places-filter-grid.matches > * {
    grid-area: unset !important;
    grid-column: 1 / -1;
    min-width: 0;
    width: 100%;
  }

  .places-filter-grid.court button,
  .places-filter-grid.court .places-filter-search-button,
  .places-filter-grid.classes .class-filter-submit {
    justify-self: stretch;
    width: 100%;
  }

  .places-discovery-filter {
    padding: var(--space-2);
  }

  .places-filter-mobile-toggle {
    align-items: start;
    background: var(--color-surface-muted);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    color: var(--color-text);
    display: grid;
    gap: 3px;
    min-height: 54px;
    padding: var(--space-2);
    text-align: left;
    width: 100%;
  }

  .places-filter-mobile-toggle span {
    font-size: var(--font-size-sm);
    font-weight: 950;
  }

  .places-filter-mobile-toggle small {
    color: var(--color-text-subtle);
    font-size: var(--font-size-xs);
    font-weight: 800;
    line-height: var(--line-title);
  }

  .places-filter-grid.court:not(.mobile-open),
  .places-filter-grid.classes:not(.mobile-open),
  .places-filter-grid.matches:not(.mobile-open) {
    display: none;
  }

  .place-public-highlights {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .place-public-hero,
  .place-public-hero.has-cover,
  .place-public-kpis,
  .place-public-grid,
  .place-public-booking-form,
  .place-public-overview-grid,
  .place-public-overview-list,
  .place-public-about-grid {
    grid-template-columns: 1fr;
  }

  .place-public-overview-header {
    display: grid;
  }

  .place-public-topbar {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .place-public-topbar > div {
    text-align: left;
  }

  .place-public-cover {
    aspect-ratio: 16 / 9;
  }

  .place-public-action-rail {
    display: flex;
    margin-inline: calc(-1 * var(--space-3));
    overflow-x: auto;
    padding: 0 var(--space-3) 2px;
    scroll-snap-type: x proximity;
  }

  .place-public-action-rail button {
    flex: 0 0 min(76vw, 260px);
    scroll-snap-align: start;
  }

  .place-public-sticky-cta {
    background: rgba(255, 255, 255, 0.94);
    border-top: 1px solid var(--color-border);
    bottom: var(--bottom-nav-height);
