/* ----- Floating add button ----- */
.fab-add {
  position: fixed;
  right: var(--space-4);
  bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + var(--space-4));
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-primary);
  color: var(--color-primary-fg);
  border: none;
  font-size: 26px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: var(--shadow-lg);
  z-index: 90;
}

.fab-add:hover {
  background: var(--color-primary-strong);
}

.fab-save {
  position: fixed;
  right: var(--space-4);
  bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + var(--space-4));
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-primary);
  color: var(--color-primary-fg);
  border: none;
  padding: 0;
  display: grid;
  place-items: center;
  box-shadow: var(--shadow-lg);
  z-index: 95;
}

.fab-save svg {
  width: 24px;
  height: 24px;
}

.fab-save:hover:not(:disabled) {
  background: var(--color-primary-strong);
}

.fab-save:disabled {
  opacity: 0.6;
}

/* ----- Modal ----- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 30, 61, 0.55);
  display: grid;
  place-items: center;
  z-index: 200;
  padding: var(--space-4);
}

.modal {
  width: min(480px, 100%);
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  box-shadow: var(--shadow-lg);
  max-height: calc(100vh - 32px);
  overflow-y: auto;
}

.modal h2 {
  margin: 0 0 var(--space-3);
  font-size: var(--font-size-lg);
}

.modal-helper {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 700;
  margin: -4px 0 var(--space-3);
}

.setup-wizard {
  display: grid;
  gap: var(--space-4);
}

.setup-wizard-head {
  align-items: flex-start;
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
}

.setup-wizard-head h2 {
  color: var(--color-text);
  font-size: var(--font-size-xl);
  font-weight: 950;
  line-height: 1.1;
  margin: 0;
}

.setup-wizard-head p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 750;
  margin: 6px 0 0;
}

.setup-wizard-head > span {
  background: var(--color-primary-soft);
  border: 1px solid var(--color-green-200);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  padding: 5px 9px;
  white-space: nowrap;
}

.setup-wizard-steps {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
}

.setup-wizard-steps button {
  align-items: flex-start;
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text-subtle);
  display: grid;
  gap: 3px;
  justify-items: start;
  min-height: 58px;
  padding: var(--space-2);
  text-align: left;
}

.setup-wizard-steps button.active,
.setup-wizard-steps button.done {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  color: var(--color-primary-strong);
}

.setup-wizard-steps strong {
  font-size: var(--font-size-xs);
  font-weight: 950;
}

.setup-wizard-steps small {
  font-size: 11px;
  font-weight: 800;
}

.setup-wizard-body {
  display: grid;
  gap: var(--space-3);
}

.setup-wizard-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: flex-end;
}

.competition-create-modal {
