}

.competition-court-usage-item.pending {
  background: var(--color-amber-100);
  border-color: #fed7aa;
}

.competition-class-list {
  display: grid;
  gap: var(--space-2);
}

.competition-class-list article {
  align-items: center;
  background: var(--color-surface-muted);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: flex;
  gap: var(--space-3);
  justify-content: space-between;
  padding: var(--space-3);
}

