.competition-class-list strong {
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 950;
}

.competition-class-list span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.competition-review {
  display: grid;
  gap: var(--space-2);
