}

.app-sheet.entity-drawer.academy-student-entity-drawer .app-overlay-body {
  min-height: 0;
  overflow: hidden;
  padding: 0;
}

.app-sheet.entity-drawer.academy-student-entity-drawer .entity-drawer-body {
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
