}

.academy-student-entity-drawer .academy-drawer-form label,
.academy-student-entity-drawer .academy-drawer-form input,
.academy-student-entity-drawer .academy-drawer-form select,
.academy-student-entity-drawer .academy-drawer-form textarea,
.academy-student-entity-drawer .academy-contract-linked-classes,
.academy-student-entity-drawer .academy-student-history article {
