  width: 100%;
}

.academy-student-entity-drawer .academy-drawer-form.compact button,
.academy-student-entity-drawer .academy-drawer-form.progress button {
  align-self: end;
}

.academy-student-entity-drawer .academy-workspace-metrics,
.academy-student-entity-drawer .academy-student-inline-actions,
.academy-student-entity-drawer .academy-contract-linked-classes {
