}

@media (max-width: 760px) {
  .app-shell--management .academy-entity-table-head {
    display: none;
  }

  .app-shell--management .academy-students-table-head,
  .app-shell--management .academy-student-row.academy-directory-row,
  .app-shell--management .academy-classes-table-head,
  .app-shell--management .academy-class-row.academy-directory-row {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .app-shell--management .academy-directory-row > span:nth-of-type(n + 3) {
    grid-column: 1 / -1;
  }

  .app-shell--management .academy-directory-row em {
    justify-self: end;
  }

  .academy-grade-toolbar,
  .crm-first-fold,
  .crm-drawer-form,
  .academy-drawer-form,
  .academy-drawer-form.compact,
  .academy-drawer-inline-form,
  .academy-class-student-list article {
    grid-template-columns: 1fr;
  }

  .academy-grade-toolbar span,
  .academy-class-student-list article > div:last-child {
    justify-content: flex-start;
    text-align: left;
  }

  .app-overlay-backdrop,
  .entity-drawer-backdrop {
    align-items: flex-end;
    background: rgba(8, 18, 37, 0.46);
    padding: 0;
  }

  .app-dialog,
  .app-sheet {
    border-bottom: 0;
    border-radius: var(--radius-xl) var(--radius-xl) 0 0;
    max-height: min(86dvh, 720px);
    max-width: none;
    position: relative;
    width: 100%;
  }

  .app-dialog {
    margin: 0;
  }

  .app-sheet-handle {
    background: var(--color-border-strong);
    border-radius: var(--radius-pill);
    display: block;
    height: 4px;
    justify-self: center;
    margin-top: 8px;
    width: 42px;
  }

  .app-overlay-header {
    padding: var(--space-4) var(--space-3) var(--space-3);
  }

  .app-overlay-body,
  .app-form-dialog-body {
    padding: var(--space-3);
  }

  .app-overlay-actions,
  .app-form-dialog-actions {
    padding: var(--space-3) var(--space-3) calc(var(--space-3) + env(safe-area-inset-bottom, 0px));
  }

  .app-overlay-actions button,
  .app-form-dialog-actions button {
    flex: 1;
  }

  .entity-drawer {
    border-bottom: 0;
    border-radius: var(--radius-xl) var(--radius-xl) 0 0;
    max-height: min(82vh, 720px);
    max-width: none;
    position: relative;
    width: 100%;
  }

  .entity-drawer::before {
    background: var(--color-border-strong);
    border-radius: var(--radius-pill);
    content: "";
    height: 4px;
    left: 50%;
    position: absolute;
    top: 8px;
    transform: translateX(-50%);
    width: 42px;
  }

  .entity-drawer header {
    padding: var(--space-5) var(--space-3) var(--space-3);
  }

  .entity-drawer-body {
    padding: var(--space-3);
  }

  .entity-drawer-actions {
    background: var(--color-surface);
    padding: var(--space-3);
  }

  .entity-drawer-actions button {
    flex: 1;
  }

  .app-sheet.entity-drawer.academy-student-entity-drawer {
    max-height: min(92dvh, 760px);
    min-height: 0;
    width: 100%;
  }

  .app-sheet.entity-drawer.academy-student-entity-drawer .entity-drawer-body {
    padding: var(--space-3);
  }

  .app-sheet.entity-drawer.academy-student-entity-drawer .app-overlay-header {
    gap: var(--space-2);
  }

  .app-sheet.entity-drawer.academy-student-entity-drawer .academy-student-drawer,
  .app-sheet.entity-drawer.academy-student-entity-drawer .academy-drawer-form,
  .app-sheet.entity-drawer.academy-student-entity-drawer .academy-drawer-form.compact,
  .app-sheet.entity-drawer.academy-student-entity-drawer .academy-drawer-form.progress {
    grid-template-columns: 1fr;
  }

  .app-sheet.entity-drawer.academy-student-entity-drawer .academy-student-drawer section {
    padding: var(--space-3);
  }

  .app-sheet.entity-drawer.academy-student-entity-drawer .app-overlay-actions {
    padding: var(--space-3) var(--space-3) calc(var(--space-3) + env(safe-area-inset-bottom, 0px));
  }

  .app-sheet.entity-drawer.academy-student-entity-drawer .entity-drawer-actions {
    align-items: stretch;
    flex-direction: column-reverse;
  }
}

/* ----- Ranking page ----- */
.ranking-hero-panel {
  background: linear-gradient(135deg, #052e2b 0%, #0f513f 62%, #155e75 100%);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  color: #fff;
  display: grid;
  gap: var(--space-4);
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.75fr);
  margin-bottom: var(--space-3);
  padding: var(--space-4);
}

.ranking-hero-panel span {
  color: rgba(255, 255, 255, 0.72);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.ranking-hero-panel h2 {
  color: #fff;
  font-size: var(--font-size-3xl);
  line-height: 1;
  margin: var(--space-2) 0;
}

.ranking-hero-panel p {
  color: rgba(255, 255, 255, 0.76);
  font-weight: 800;
  margin: 0;
  max-width: 620px;
}

.ranking-hero-kpis {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ranking-hero-kpis article {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: var(--radius-md);
  padding: var(--space-3);
}

.ranking-hero-kpis strong {
  color: #fff;
  display: block;
  font-size: var(--font-size-2xl);
  line-height: 1;
}

.ranking-player-overview {
  align-items: stretch;
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(0, 1.4fr) minmax(220px, 0.8fr);
  margin-bottom: var(--space-3);
}

.ranking-player-position,
.ranking-player-context {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: var(--space-1);
  padding: var(--space-4);
}

.ranking-player-position {
  grid-template-columns: auto minmax(0, 1fr);
}

.ranking-player-position > span,
.ranking-player-context > span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 950;
  grid-column: 1 / -1;
  text-transform: uppercase;
}

.ranking-player-position > strong {
  align-items: center;
  background: var(--color-primary-soft);
  border: 1px solid var(--color-green-200);
  border-radius: var(--radius-md);
  color: var(--color-primary-strong);
  display: inline-flex;
  font-size: var(--font-size-3xl);
  font-weight: 950;
  justify-content: center;
  min-height: 86px;
  min-width: 92px;
  padding: var(--space-2);
}

.ranking-player-position h2 {
  align-self: end;
  color: var(--color-text);
  font-size: var(--font-size-xl);
  line-height: var(--line-tight);
  margin: 0;
}

.ranking-player-position p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 850;
  grid-column: 2;
  margin: 0;
}

.ranking-player-context strong {
  color: var(--color-text);
  font-size: var(--font-size-lg);
  line-height: var(--line-tight);
}

.ranking-player-context small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 850;
}

.ranking-control-panel {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xs);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
}

.ranking-scope-tabs,
.ranking-filters {
  display: grid;
  gap: var(--space-2);
}

.ranking-scope-tabs {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ranking-scope-tabs button {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text-muted);
  font-weight: 900;
}

.ranking-scope-tabs button.active {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  color: var(--color-primary-strong);
}

.ranking-filters {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: var(--space-2);
}

.ranking-filter-summary {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
  margin: var(--space-2) 0 0;
}

.ranking-filter-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: var(--space-2);
}

.ranking-filter-actions button {
  min-height: 34px;
  padding: 5px 12px;
}

.ranking-list-shell {
  display: grid;
  gap: var(--space-2);
}

.ranking-list-head {
  align-items: end;
  display: flex;
  gap: var(--space-2);
  justify-content: space-between;
}

.ranking-list-head span {
  color: var(--color-primary-strong);
  display: block;
  font-size: var(--font-size-xs);
  font-weight: 950;
  text-transform: uppercase;
}

.ranking-list-head h2 {
  color: var(--color-text);
  font-size: var(--font-size-xl);
  line-height: var(--line-tight);
  margin: 0;
}

.ranking-list-head small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
  white-space: nowrap;
}

.ranking-load-more {
  display: flex;
  justify-content: center;
  margin-top: var(--space-1);
}

.ranking-load-more button {
  min-width: min(100%, 260px);
}

.place-report-peaks {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: var(--space-3);
}

.place-report-peaks div {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  display: grid;
  gap: 3px;
  padding: var(--space-2);
}

.place-report-peaks span {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.place-report-peaks strong {
  color: var(--color-text);
  font-size: var(--font-size-lg);
}

.place-report-peaks small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.ranking-my-card {
  background: var(--color-primary-soft);
  border: 1px solid var(--color-green-200);
  border-radius: var(--radius-md);
  display: grid;
  gap: var(--space-1);
  margin-bottom: var(--space-3);
  padding: var(--space-3);
}

.ranking-my-card strong {
  color: var(--color-primary-strong);
}

.ranking-my-card span {
  color: var(--color-text);
  font-size: var(--font-size-sm);
  font-weight: 800;
}

.ranking-feature-grid {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-bottom: var(--space-3);
}

.ranking-leader-card,
.ranking-player-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xs);
  display: grid;
  gap: 5px;
  padding: var(--space-3);
}

.ranking-leader-card {
  background: #fffbeb;
  border-color: #fde68a;
}

.ranking-leader-card > span,
.ranking-player-card > span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.ranking-leader-card strong,
.ranking-player-card strong {
  color: var(--color-text);
  font-size: var(--font-size-lg);
}

.ranking-leader-card small,
.ranking-player-card small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 800;
}

.ranking-leader-card div,
.ranking-player-card div {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-1);
}

.ranking-leader-card b,
.ranking-player-card b {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  font-size: var(--font-size-xs);
  padding: 4px 9px;
}

.ranking-ops-grid {
  display: grid;
  gap: var(--space-2);
  grid-template-columns: minmax(0, 1.1fr) minmax(280px, 0.9fr);
  margin-bottom: var(--space-3);
}

.ranking-rules-card,
.ranking-race-card,
.ranking-class-map-card,
.ranking-tools-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xs);
  display: grid;
  gap: var(--space-2);
  padding: var(--space-3);
}

.ranking-rules-card > span,
.ranking-race-card > span,
.ranking-class-map-card > span,
.ranking-tools-card > span {
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.ranking-rules-card h3,
.ranking-race-card h3,
.ranking-class-map-card h3,
.ranking-tools-card h3 {
  color: var(--color-text);
  margin: 0;
}

.ranking-rules-card div,
.ranking-race-card div,
.ranking-class-map-card div,
.ranking-tools-card div {
  display: grid;
  gap: var(--space-2);
}

.ranking-rules-card p,
.ranking-race-card p,
.ranking-class-map-card p,
.ranking-tools-card p {
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  display: grid;
  gap: 3px;
  margin: 0;
  min-width: 0;
  padding: var(--space-2);
}

.ranking-rules-card b,
.ranking-race-card b,
.ranking-class-map-card b {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  text-transform: uppercase;
}

.ranking-rules-card strong,
.ranking-race-card strong,
.ranking-class-map-card strong {
  color: var(--color-text);
  min-width: 0;
}

.ranking-race-card p {
  align-items: center;
  grid-template-columns: 44px minmax(0, 1fr) auto;
}

.ranking-race-card em {
  background: var(--color-primary-soft);
  border: 1px solid var(--color-green-200);
  border-radius: var(--radius-pill);
  color: var(--color-primary-strong);
  font-size: var(--font-size-xs);
  font-style: normal;
  font-weight: 900;
  padding: 4px 9px;
  white-space: nowrap;
}

.ranking-class-map-card em {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-style: normal;
  font-weight: 850;
}

.ranking-tools-card div {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.ranking-tools-card .publishing-kit,
.place-public-channel-card .publishing-kit {
  margin: 0 0 var(--space-2);
}

.ranking-tools-card .publishing-kit {
  grid-template-columns: minmax(220px, 1fr) repeat(2, auto);
}

.ranking-tools-card .publishing-kit > div,
.place-public-channel-card .publishing-kit > div {
  grid-template-columns: none;
}

.ranking-tools-card .publishing-kit-actions,
.place-public-channel-card .publishing-kit-actions {
  display: contents;
}

.ranking-tools-card p {
  color: var(--color-text-subtle);
  font-size: var(--font-size-sm);
  font-weight: 800;
  line-height: var(--line-normal);
}

.ranking-rules-card small,
.ranking-race-card small,
.ranking-class-map-card small,
.ranking-tools-card small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 800;
}

.ranking-table {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  overflow-x: auto;
}

.ranking-row {
  align-items: center;
  display: grid;
  gap: var(--space-2);
  grid-template-columns: 44px minmax(150px, 1fr) minmax(180px, 1.2fr) 64px 64px 92px;
  min-width: 760px;
  padding: var(--space-2) var(--space-3);
}

.ranking-row + .ranking-row {
  border-top: 1px solid var(--color-border);
}

.ranking-row.head {
  background: #f8fafc;
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
  font-weight: 900;
  text-transform: uppercase;
}

.ranking-row.mine {
  background: #ecfdf5;
}

.ranking-row strong,
.ranking-row small {
  display: block;
  min-width: 0;
}

.ranking-row small {
  color: var(--color-text-subtle);
  font-size: var(--font-size-xs);
}

.ranking-row button {
  min-height: 32px;
  padding: 5px 10px;
  width: 100%;
}

.ranking-row .ranking-follow-button {
  background: var(--color-surface);
  border-color: var(--color-border);
  color: var(--color-primary-strong);
  min-height: 36px;
}

.ranking-row .ranking-follow-button.active {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  color: var(--color-primary-strong);
}

.ranking-secondary-panel {
  display: grid;
  gap: var(--space-2);
  margin-top: var(--space-3);
}

.ranking-secondary-panel summary {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  font-size: var(--font-size-sm);
  font-weight: 950;
  justify-content: center;
  list-style: none;
  min-height: 42px;
  padding: 0 var(--space-3);
  width: fit-content;
}

.ranking-secondary-panel summary::-webkit-details-marker {
  display: none;
}

.ranking-secondary-panel[open] summary {
  background: var(--color-primary-soft);
  border-color: var(--color-green-200);
  color: var(--color-primary-strong);
  margin-bottom: var(--space-2);
}

@media (max-width: 760px) {
  .ranking-scope-tabs,
  .ranking-filters,
  .ranking-hero-panel,
  .ranking-hero-kpis,
  .ranking-player-overview,
  .ranking-list-head,
  .ranking-feature-grid,
  .ranking-ops-grid {
    grid-template-columns: 1fr;
  }

  .ranking-list-head {
    align-items: start;
    display: grid;
  }

  .ranking-list-head small {
    white-space: normal;
  }

  .ranking-scope-tabs {
    display: flex;
    overflow-x: auto;
    scroll-snap-type: x proximity;
  }

