    font-size: var(--font-size-2xl);
    min-height: 70px;
    min-width: 70px;
  }

  .ranking-player-position p {
    grid-column: 1 / -1;
  }

  .ranking-race-card p {
    grid-template-columns: 36px minmax(0, 1fr);
  }

  .ranking-race-card em {
    grid-column: 2;
    justify-self: flex-start;
  }

  .ranking-table {
    background: transparent;
    border: 0;
    box-shadow: none;
    display: grid;
    gap: var(--space-2);
    overflow: visible;
  }

  .ranking-row.head {
    display: none;
  }

  .ranking-row {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-xs);
    grid-template-columns: 42px minmax(0, 1fr) 72px;
    min-width: 0;
  }

  .ranking-row + .ranking-row {
    border-top: 1px solid var(--color-border);
  }

  .ranking-row > span:first-child {
    align-items: center;
    background: var(--color-surface-muted);
    border-radius: var(--radius-sm);
    display: inline-flex;
    font-weight: 950;
    grid-row: 1 / span 2;
    justify-content: center;
    min-height: 42px;
  }

  .ranking-row > span:nth-child(2) {
    grid-column: 2;
  }

  .ranking-row > span:nth-child(3) {
    grid-column: 2 / -1;
  }

  .ranking-row > span:nth-child(4) {
    grid-column: 3;
    grid-row: 1;
    text-align: right;
  }

  .ranking-row > span:nth-child(5) {
    font-weight: 950;
    grid-column: 3;
    grid-row: 2;
    text-align: right;
  }

  .ranking-row > span:nth-child(6) {
    grid-column: 2 / -1;
    justify-self: end;
  }

  .ranking-row button {
    min-width: 84px;
    width: auto;
  }
