/* ----- PDARK-17: empty states, feedback, overlays and setup wizard ----- */
.screen-state,
.empty-state,
.home-empty-panel,
.home-empty-inline,
.home-today-empty,
.workspace-empty-state,
.management-empty-state,
.app-compact-empty,
.place-public-booking-empty,
.place-public-overview-empty,
.court-calendar-empty-slot {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(166, 198, 229, 0.16);
  background:
    linear-gradient(180deg, rgba(10, 26, 44, 0.9), rgba(5, 15, 28, 0.86)),
    url("./assets/pdark-empty-state-court-texture.png") center / cover no-repeat;
  color: var(--pdark-text-main);
  box-shadow: 0 18px 46px rgba(0, 0, 0, 0.22);
}

.screen-state::before,
.empty-state::before,
.home-empty-panel::before,
.workspace-empty-state::before,
.management-empty-state::before,
.app-compact-empty::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 82% 16%, rgba(74, 222, 128, 0.16), transparent 28%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent 34%);
}

.screen-state > *,
.empty-state > *,
.home-empty-panel > *,
.workspace-empty-state > *,
.management-empty-state > *,
.app-compact-empty > * {
  position: relative;
  z-index: 1;
}

.screen-state > strong,
.empty-state strong,
.home-empty-panel strong,
.home-empty-inline strong,
.home-today-empty strong,
.workspace-empty-state strong,
.management-empty-state h2,
.app-compact-empty strong,
.place-public-booking-empty strong,
.place-public-overview-empty strong {
  color: #ffffff;
}

.screen-state p,
.empty-state p,
.empty-state small,
.home-empty-panel span,
.home-empty-inline span,
.home-today-empty span,
.workspace-empty-state span,
.workspace-empty-state small,
.management-empty-state p,
