  place-items: center;
  border-radius: 16px;
  background: rgba(34, 197, 94, 0.16);
  color: #8ff5b5;
  box-shadow: inset 0 0 0 1px rgba(74, 222, 128, 0.22);
}

.screen-state-loading::after {
  content: "";
  position: absolute;
  inset: auto 22px 18px 22px;
  height: 4px;
  border-radius: 999px;
  background:
    linear-gradient(90deg, transparent, rgba(74, 222, 128, 0.9), transparent) 0 0 / 38% 100% no-repeat,
    rgba(255, 255, 255, 0.08);
  animation: pdark-loading-scan 1.35s ease-in-out infinite;
}

@keyframes pdark-loading-scan {
  0% {
    background-position: -45% 0, 0 0;
